public.fn_agent_wallet_self_stake(p_club.def:
CREATE OR REPLACE FUNCTION public.fn_agent_wallet_self_stake(p_club_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_prior record;
  v_role text;
  v_wallet_after numeric;
  v_player_after numeric;
  v_tx uuid;
  v_context jsonb;
  v_setting text;
begin
  if v_actor is null then
    return jsonb_build_object('success',false,'error','Not Authenticated');
  end if;
  if p_op_id is null then
    return jsonb_build_object('success',false,'error','A Retry Key Is Required For Every Send');
  end if;
  if p_club_id is null then
    return jsonb_build_object('success',false,'error','That Club Could Not Be Found');
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 1e9 or p_amount <> round(p_amount,2) then
    return jsonb_build_object('success',false,'error','Enter A Valid Send Amount');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'agent-wallet-send:'||p_club_id::text||':'||v_actor::text||':'||p_op_id::text,0));
  perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));

  select ct.* into v_prior from public.chip_transactions ct
   where ct.club_id=p_club_id and ct.transaction_type='agent_wallet_self_stake'
     and ct.from_user_id=v_actor and ct.metadata->>'op_id'=p_op_id::text limit 1;
  if found then
    if v_prior.amount is distinct from p_amount then
      return jsonb_build_object('success',false,
        'error','That Retry Key Belongs To A Different Agent Wallet Send');
    end if;
    return jsonb_build_object('success',true,'replayed',true,
      'transaction_id',v_prior.id,'amount',v_prior.amount,
      'agent_wallet_after',(v_prior.metadata->>'agent_wallet_after')::numeric,
      'player_wallet_after',(v_prior.metadata->>'player_wallet_after')::numeric);
  end if;

  perform 1 from public.clubs where id=p_club_id for update;
  if not found then
    return jsonb_build_object('success',false,'error','That Club Could Not Be Found');
  end if;
  perform 1 from public.club_members where club_id=p_club_id and user_id=v_actor for update;

  v_role := public.fn_club_bank_role(p_club_id, v_actor);
  -- Dan 2026-09-02: owners and co-owners hold a player wallet again, and they
  -- have always held an agent wallet, so the rung exists for them too. An
  -- admin holds no player wallet, so there is nowhere for the chips to land.
  if v_role is null or v_role not in ('owner','co_owner','super_agent','agent','sub_agent') then
    return jsonb_build_object('success',false,'error','Only An Agent Wallet Holder With A Player Wallet Can Stake Their Own Seat');
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE `agent_send` row from the agent's own
  -- float to their own player wallet, keyed and correlated on the op (32
  -- stakes / 320,000.00 in 30d journaled as two suspense legs). The agents
  -- trigger is skipped; the club_members trigger writes the row.
  SELECT jsonb_object_agg(k,coalesce(current_setting(k,true),'')) INTO v_context
   FROM unnest(array['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_tournament','app.ledger_settlement','app.ledger_idempotency_key','app.ledger_correlation','app.ledger_autoskip_agents']) settings(k);
  PERFORM set_config('app.ledger_tournament','',true);
  PERFORM set_config('app.ledger_settlement','',true);
  perform public.fn_ca_declare_ledger('agent_send', 'agent_wallet', v_actor, null,
    'agent_self_stake:' || p_op_id::text, array['agents']);
  perform set_config('app.ledger_correlation', p_op_id::text, true);

  update public.agents
     set agent_wallet_balance = agent_wallet_balance - p_amount
   where club_id=p_club_id and user_id=v_actor
     and coalesce(status,'active')='active'
     and agent_wallet_balance >= p_amount
   returning agent_wallet_balance into v_wallet_after;
  if v_wallet_after is null then
  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;
    return jsonb_build_object('success',false,'error','Your Agent Wallet Cannot Cover That Amount');
  end if;

  update public.club_members
     set chip_balance = coalesce(chip_balance,0) + p_amount
   where club_id=p_club_id and user_id=v_actor
   returning chip_balance into v_player_after;
  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;
  if v_player_after is null then
    raise exception 'membership row vanished for % in % after wallet debit', v_actor, p_club_id;
  end if;

  insert into public.chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, v_actor, v_actor, p_amount, 'agent_wallet_self_stake',
     coalesce(p_reason,'Agent Wallet To Own Player Wallet'),
     jsonb_build_object('op_id',p_op_id::text,'destination','player_wallet',
       'actor_role',v_role,
       'agent_wallet_after',v_wallet_after,'player_wallet_after',v_player_after),
     v_player_after)
  returning id into v_tx;

  return jsonb_build_object('success',true,'transaction_id',v_tx,'amount',p_amount,
    'agent_wallet_after',v_wallet_after,'player_wallet_after',v_player_after);
end
$function$

public.fn_ca_horse_split_wallet_leg(p_op.def:
CREATE OR REPLACE FUNCTION public.fn_ca_horse_split_wallet_leg(p_op uuid, p_kind text, p_club uuid, p_horse uuid, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_key uuid := public.fn_ca_horse_split_op_key(p_op, p_kind, p_club, p_horse);
  v_bank_before numeric; v_bank_after numeric; v_before numeric; v_after numeric; v_agent uuid;
  v_type text; v_reason text;
BEGIN
  IF EXISTS (SELECT 1 FROM public.ca_horse_club_split_receipts r
              WHERE r.operation_id = p_op AND r.horse_id = p_horse AND r.club_id = p_club AND r.kind = p_kind) THEN
    RETURN jsonb_build_object('replayed', true);
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN jsonb_build_object('skipped', true); END IF;

  SELECT coalesce(c.chip_treasury,0) INTO v_bank_before FROM public.clubs c WHERE c.id = p_club FOR UPDATE;
  IF v_bank_before IS NULL THEN RAISE EXCEPTION 'horse_split_club_missing %', p_club; END IF;

  IF p_kind IN ('player_wallet_claim', 'settle_wallet_claim', 'late_wallet_claim') THEN
    v_type := 'club_bank_claim'; v_reason := 'Horse Club Split: Wallet Returned To The Club Bank (Dan, 2026-11-02)';
    SELECT coalesce(cm.chip_balance,0) INTO v_before FROM public.club_members cm
     WHERE cm.club_id = p_club AND cm.user_id = p_horse FOR UPDATE;
    IF v_before < p_amount THEN RAISE EXCEPTION 'horse_split_wallet_short % % % %', p_club, p_horse, v_before, p_amount; END IF;
    PERFORM public.fn_ca_declare_ledger('club_bank_claim', 'club_treasury', p_club, NULL,
      'club_bank_claim:' || v_key::text, ARRAY['clubs']);
    PERFORM set_config('app.ledger_correlation', v_key::text, true);
    UPDATE public.club_members SET chip_balance = coalesce(chip_balance,0) - p_amount, updated_at = now()
     WHERE club_id = p_club AND user_id = p_horse RETURNING chip_balance INTO v_after;
    UPDATE public.clubs SET chip_treasury = coalesce(chip_treasury,0) + p_amount, updated_at = now()
     WHERE id = p_club RETURNING chip_treasury INTO v_bank_after;
  ELSIF p_kind = 'agent_wallet_claim' THEN
    v_type := 'club_bank_claim'; v_reason := 'Horse Club Split: Agent Wallet Returned To The Club Bank (Dan, 2026-11-02)';
    SELECT a.id, coalesce(a.agent_wallet_balance,0) INTO v_agent, v_before FROM public.agents a
     WHERE a.club_id = p_club AND a.user_id = p_horse FOR UPDATE;
    IF v_agent IS NULL OR v_before < p_amount THEN RAISE EXCEPTION 'horse_split_agent_wallet_short % %', p_club, p_horse; END IF;
    PERFORM public.fn_ca_declare_ledger('club_bank_claim', 'club_treasury', p_club, NULL,
      'club_bank_claim:' || v_key::text, ARRAY['clubs']);
    PERFORM set_config('app.ledger_correlation', v_key::text, true);
    UPDATE public.agents SET agent_wallet_balance = coalesce(agent_wallet_balance,0) - p_amount, updated_at = now()
     WHERE id = v_agent RETURNING agent_wallet_balance INTO v_after;
    UPDATE public.clubs SET chip_treasury = coalesce(chip_treasury,0) + p_amount, updated_at = now()
     WHERE id = p_club RETURNING chip_treasury INTO v_bank_after;
  ELSIF p_kind = 'fund_10000' THEN
    v_type := 'club_bank_send'; v_reason := 'Horse Club Split: Restart At 10,000 (Dan, 2026-11-02)';
    IF v_bank_before < p_amount THEN RAISE EXCEPTION 'horse_split_bank_short % % %', p_club, v_bank_before, p_amount; END IF;
    SELECT coalesce(cm.chip_balance,0) INTO v_before FROM public.club_members cm
     WHERE cm.club_id = p_club AND cm.user_id = p_horse FOR UPDATE;
    PERFORM public.fn_ca_declare_ledger('club_bank_send', 'club_treasury', p_club, NULL,
      'club_bank_send:' || v_key::text, ARRAY['clubs']);
    PERFORM set_config('app.ledger_correlation', v_key::text, true);
    UPDATE public.clubs SET chip_treasury = coalesce(chip_treasury,0) - p_amount, updated_at = now()
     WHERE id = p_club RETURNING chip_treasury INTO v_bank_after;
    UPDATE public.club_members SET chip_balance = coalesce(chip_balance,0) + p_amount, updated_at = now()
     WHERE club_id = p_club AND user_id = p_horse RETURNING chip_balance INTO v_after;
  ELSE
    RAISE EXCEPTION 'horse_split_unknown_leg %', p_kind;
  END IF;
  PERFORM set_config('app.ledger_autoskip_clubs', '', true);

  INSERT INTO public.chip_transactions(club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  VALUES (p_club,
          CASE WHEN v_type = 'club_bank_claim' THEN p_horse END,
          CASE WHEN v_type = 'club_bank_send' THEN p_horse END,
          p_amount, v_type, v_reason,
          jsonb_build_object('op_id', v_key, 'operation', 'horse-club-split-20261102', 'operation_id', p_op,
            'leg', p_kind, 'actor', 'horse_club_split_operation',
            'source', CASE WHEN p_kind='agent_wallet_claim' THEN 'agent_wallet' WHEN p_kind IN ('player_wallet_claim','settle_wallet_claim') THEN 'player_wallet' ELSE 'club_bank' END,
            'destination', CASE WHEN v_type='club_bank_send' THEN 'player_wallet' ELSE 'club_bank' END,
            'bank_before', v_bank_before, 'bank_after', v_bank_after,
            'holder_balance_before', v_before, 'holder_balance_after', v_after),
          v_bank_after);

  INSERT INTO public.ca_horse_club_split_receipts(operation_id, horse_id, club_id, kind, amount,
    wallet_before, wallet_after, bank_before, bank_after, op_key)
  VALUES (p_op, p_horse, p_club, p_kind, p_amount, v_before, v_after, v_bank_before, v_bank_after, v_key);
  RETURN jsonb_build_object('amount', p_amount, 'bank_after', v_bank_after, 'wallet_after', v_after);
END $function$

public.fn_club_bank_claim_core_20261004(.def:
CREATE OR REPLACE FUNCTION public.fn_club_bank_claim_core_20261004(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_source text DEFAULT 'agent_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_source       text := lower(coalesce(p_source, 'agent_wallet'));
  v_op_id        uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior        record;
  v_holder_role  text;
  v_held         numeric;
  v_agent_id     uuid;
  v_holder_after numeric;
  v_bank_after   numeric;
  v_tx_id        uuid;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner Or Admin May Claim Chips Back Into The Club Bank');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'club_bank_claim'
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'source', v_prior.metadata ->> 'source',
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric,
      'holder_balance_after', (v_prior.metadata ->> 'holder_balance_after')::numeric);
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Claim Limit');
  end if;
  if v_source not in ('agent_wallet', 'promo_wallet', 'player_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Source Wallet');
  end if;
  if p_from_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose Whose Wallet To Claim From');
  end if;

  if p_from_user_id <> v_actor
     and not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_from_user_id) then
    return jsonb_build_object('success', false,
      'error', 'That Member Is Not In Your Downline');
  end if;

  select cm.role into v_holder_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_from_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_holder_role is null then
    return jsonb_build_object('success', false, 'error', 'That Person Is Not An Active Member Of This Club');
  end if;

  if v_source = 'player_wallet' then
    select coalesce(chip_balance, 0) into v_held
      from club_members
     where club_id = p_club_id and user_id = p_from_user_id
     for update;
  else
    if v_holder_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
      return jsonb_build_object('success', false,
        'error', 'Only Staff Or Agents Hold An Agent Wallet');
    end if;
    select a.id, coalesce(case when v_source = 'promo_wallet'
                               then a.promo_wallet_balance
                               else a.agent_wallet_balance end, 0)
      into v_agent_id, v_held
      from agents a
     where a.club_id = p_club_id and a.user_id = p_from_user_id
     for update;
    if v_agent_id is null then
      return jsonb_build_object('success', false,
        'error', 'That Member Has Never Been Funded, So There Is Nothing To Claim');
    end if;
  end if;

  if v_held < p_amount then
    return jsonb_build_object('success', false,
      'error', 'That Wallet Only Holds ' || trim(to_char(v_held, 'FM999,999,999,990.00')) || ' Chips',
      'held', v_held, 'requested', p_amount);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE row from the wallet claimed to the
  -- club bank, keyed and correlated on the op. The clubs trigger is skipped;
  -- the holder's wallet trigger writes the row with the bank as counterparty.
  perform public.fn_ca_declare_ledger('club_bank_claim', CASE WHEN v_source='promo_wallet' THEN 'promo_wallet' ELSE 'club_treasury' END, p_club_id, null,
    'club_bank_claim:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  if v_source = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) - p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_from_user_id
     returning chip_balance into v_holder_after;
  elsif v_source = 'promo_wallet' then
    update agents
       set promo_wallet_balance = coalesce(promo_wallet_balance, 0) - p_amount,
           updated_at = now()
     where id = v_agent_id
     returning promo_wallet_balance into v_holder_after;
  else
    update agents
       set agent_wallet_balance = coalesce(agent_wallet_balance, 0) - p_amount,
           updated_at = now()
     where id = v_agent_id
     returning agent_wallet_balance into v_holder_after;
  end if;

  update clubs
     set chip_treasury = coalesce(chip_treasury, 0) + CASE WHEN v_source='promo_wallet' THEN 0 ELSE p_amount END, promo_balance = coalesce(promo_balance,0) + CASE WHEN v_source='promo_wallet' THEN p_amount ELSE 0 END,
         updated_at = now()
   where id = p_club_id
   returning CASE WHEN v_source='promo_wallet' THEN promo_balance ELSE chip_treasury END into v_bank_after;
  if v_bank_after is null then
    raise exception 'club % not found while crediting the bank', p_club_id;
  end if;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, p_from_user_id, v_actor, p_amount, 'club_bank_claim',
     coalesce(nullif(btrim(p_reason), ''), 'Club Bank Claim Back'),
     jsonb_build_object(
       'op_id', v_op_id,
       'source', v_source, 'destination', CASE WHEN v_source='promo_wallet' THEN 'club_promo_wallet' ELSE 'club_bank' END,
       'direction', 'into_bank',
       'actor_role', v_actor_role,
       'holder_role', v_holder_role,
       'bank_after', v_bank_after,
       'holder_balance_after', v_holder_after),
     v_bank_after)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'source', v_source, 'destination', CASE WHEN v_source='promo_wallet' THEN 'club_promo_wallet' ELSE 'club_bank' END,
    'bank_after', v_bank_after,
    'holder_balance_after', v_holder_after);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where club_id = p_club_id
       and transaction_type = 'club_bank_claim'
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'source', v_prior.metadata ->> 'source',
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric,
      'holder_balance_after', (v_prior.metadata ->> 'holder_balance_after')::numeric);
end
$function$

public.fn_club_bank_reverse_core_2026100.def:
CREATE OR REPLACE FUNCTION public.fn_club_bank_reverse_core_20261004(p_transaction_id uuid, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor      uuid := auth.uid();
  v_actor_role text;
  v_op_id      uuid := coalesce(p_op_id, gen_random_uuid());
  v_tx         record;
  v_dest       text;
  v_held       numeric;
  v_agent_id   uuid;
  v_bank_after numeric;
  v_to_after   numeric;
  v_new_id     uuid;
  v_prior      record;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  select id, club_id, from_user_id, to_user_id, amount, transaction_type,
         coalesce(metadata, '{}'::jsonb) as metadata,
         coalesce(is_reversed, false) as is_reversed, reversible_until
    into v_tx
    from chip_transactions
   where id = p_transaction_id
   for update;
  if v_tx.id is null then
    return jsonb_build_object('success', false, 'error', 'That Ledger Entry Was Not Found');
  end if;

  v_actor_role := public.fn_club_bank_role(v_tx.club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner Or Admin May Reverse A Club Bank Send');
  end if;

  select id into v_prior from chip_transactions
   where club_id = v_tx.club_id
     and transaction_type = 'club_bank_reversal'
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object('success', true, 'replayed', true, 'transaction_id', v_prior.id);
  end if;

  if v_tx.transaction_type <> 'club_bank_send' then
    return jsonb_build_object('success', false,
      'error', 'Only A Club Bank Send Can Be Reversed Here');
  end if;
  if v_tx.is_reversed then
    return jsonb_build_object('success', false, 'error', 'That Send Has Already Been Reversed');
  end if;
  if v_tx.reversible_until is not null and now() > v_tx.reversible_until then
    return jsonb_build_object('success', false,
      'error', 'That Send Is Outside Its Seven Day Reversal Window');
  end if;

  v_dest := coalesce(v_tx.metadata ->> 'destination', 'agent_wallet');

  -- Take the chips back only if they are still there.
  if v_dest = 'player_wallet' then
    select coalesce(chip_balance, 0) into v_held
      from club_members
     where club_id = v_tx.club_id and user_id = v_tx.to_user_id
     for update;
  else
    select a.id, coalesce(case when v_dest = 'promo_wallet'
                               then a.promo_wallet_balance
                               else a.agent_wallet_balance end, 0)
      into v_agent_id, v_held
      from agents a
     where a.club_id = v_tx.club_id and a.user_id = v_tx.to_user_id
     for update;
  end if;

  if v_held is null then
    return jsonb_build_object('success', false, 'error', 'That Wallet No Longer Exists');
  end if;
  if v_held < v_tx.amount then
    return jsonb_build_object('success', false,
      'error', 'Those Chips Have Already Been Spent, So The Send Cannot Be Reversed',
      'held', v_held, 'required', v_tx.amount);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE `reversal` row from the wallet that
  -- received the send back to the club bank, keyed and correlated on the op.
  -- The clubs trigger is skipped; the recipient's wallet trigger writes it.
  perform public.fn_ca_declare_ledger('reversal', 'club_treasury', v_tx.club_id, null,
    'club_bank_reversal:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  if v_dest = 'player_wallet' then
    update club_members set chip_balance = chip_balance - v_tx.amount, updated_at = now()
     where club_id = v_tx.club_id and user_id = v_tx.to_user_id
     returning chip_balance into v_to_after;
  elsif v_dest = 'promo_wallet' then
    update agents set promo_wallet_balance = promo_wallet_balance - v_tx.amount, updated_at = now()
     where id = v_agent_id returning promo_wallet_balance into v_to_after;
  else
    update agents set agent_wallet_balance = agent_wallet_balance - v_tx.amount, updated_at = now()
     where id = v_agent_id returning agent_wallet_balance into v_to_after;
  end if;

  update clubs set chip_treasury = coalesce(chip_treasury, 0) + v_tx.amount, updated_at = now()
   where id = v_tx.club_id returning chip_treasury into v_bank_after;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  update chip_transactions
     set is_reversed = true, clawed_back = true
   where id = v_tx.id;

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (v_tx.club_id, v_tx.to_user_id, v_tx.from_user_id, v_tx.amount, 'club_bank_reversal',
     coalesce(nullif(btrim(p_reason), ''), 'Club Bank Send Reversed'),
     jsonb_build_object(
       'op_id', v_op_id,
       'reverses', v_tx.id,
       'destination', v_dest,
       'actor_role', v_actor_role,
       'bank_after', v_bank_after,
       'recipient_balance_after', v_to_after),
     v_bank_after)
  returning id into v_new_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_new_id, 'reversed', v_tx.id,
    'amount', v_tx.amount, 'bank_after', v_bank_after,
    'recipient_balance_after', v_to_after);
end
$function$

public.fn_ca_settle_approved_agent_adjus.def:
CREATE OR REPLACE FUNCTION public.fn_ca_settle_approved_agent_adjustment(p_adjustment uuid, p_club uuid, p_expected_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '1s'
AS $function$
DECLARE a public.ca_manual_adjustments%ROWTYPE; g public.agents%ROWTYPE;
 l public.chip_ledger%ROWTYPE; intent jsonb; key text; n int;
 bank_before numeric;bank_after numeric;wallet_before numeric;wallet_after numeric;
 saved jsonb;setting text;result jsonb;
BEGIN
 IF session_user<>'postgres' OR current_user<>'postgres' THEN RAISE EXCEPTION 'approved_agent_adjustment_postgres_only' USING ERRCODE='42501';END IF;
 IF p_adjustment IS NULL OR p_club IS NULL OR p_expected_payload IS NULL OR jsonb_typeof(p_expected_payload)<>'object' THEN RAISE EXCEPTION 'approved_agent_adjustment_exact_payload_required' USING ERRCODE='22023';END IF;
 SELECT*INTO STRICT a FROM public.ca_manual_adjustments WHERE id=p_adjustment FOR UPDATE;
 intent:=jsonb_build_object('club_id',p_club,'approved_adjustment',to_jsonb(a)-'status');
 IF intent IS DISTINCT FROM p_expected_payload THEN RAISE EXCEPTION 'approved_agent_adjustment_payload_changed' USING ERRCODE='23514';END IF;
 IF a.target_kind<>'agent_wallet' OR a.asset<>'chips' OR a.target_id IS NULL OR a.approver IS NULL OR a.approver=a.actor OR a.approved_at IS NULL OR a.amount<=0 OR a.amount<>round(a.amount,2) OR a.amount::text IN('NaN','Infinity','-Infinity') OR length(btrim(a.reason))<20 THEN RAISE EXCEPTION 'approved_agent_adjustment_not_positive_approved_chips' USING ERRCODE='23514';END IF;
 key:='manual-agent-adjustment:'||p_adjustment;
 SELECT count(*)INTO n FROM public.chip_ledger WHERE idempotency_key=key;
 IF a.status='settled' THEN
  IF n<>1 THEN RAISE EXCEPTION 'approved_agent_adjustment_settled_receipt_missing_or_ambiguous' USING ERRCODE='23514';END IF;
  SELECT*INTO STRICT l FROM public.chip_ledger WHERE idempotency_key=key;
  IF l.status IS DISTINCT FROM 'posted' OR l.category NOT IN('correction','commission') OR l.club_id IS DISTINCT FROM p_club OR l.from_type IS DISTINCT FROM 'club_treasury' OR l.from_entity_id IS DISTINCT FROM p_club OR l.to_type IS DISTINCT FROM 'agent_wallet' OR l.to_entity_id IS DISTINCT FROM a.target_id OR l.amount IS DISTINCT FROM a.amount OR l.correlation_id IS DISTINCT FROM a.id OR l.performed_by IS DISTINCT FROM '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid OR l.metadata->>'approved_actor'IS DISTINCT FROM a.actor::text OR l.metadata->>'approved_by'IS DISTINCT FROM a.approver::text OR l.metadata->>'paid_to'IS DISTINCT FROM 'agent_wallet' OR l.metadata->>'executed_by_db_role'IS DISTINCT FROM 'postgres' OR l.metadata->>'executed_by_session_user'IS DISTINCT FROM 'postgres' OR l.metadata->'approved_intent'IS DISTINCT FROM intent OR l.metadata->>'approved_intent_md5'IS DISTINCT FROM md5(intent::text) OR l.pre_from_balance-l.post_from_balance IS DISTINCT FROM a.amount OR l.post_to_balance-l.pre_to_balance IS DISTINCT FROM a.amount THEN RAISE EXCEPTION 'approved_agent_adjustment_replay_receipt_changed' USING ERRCODE='23514';END IF;
  IF l.category='commission' AND (SELECT count(*) FROM public.settlement_invoices i WHERE i.source_ledger_id=l.id AND i.club_id=p_club AND i.invoice_type='club_to_agent' AND i.from_entity_type='club' AND i.from_entity_id=p_club::text AND i.to_entity_type='agent' AND i.to_entity_id=a.target_id::text AND i.gross_amount=a.amount AND i.net_amount=a.amount AND i.deductions=0 AND i.status='paid' AND i.chips_transferred IS TRUE AND i.transferred_at=l.created_at AND i.invoice_number IS NOT NULL AND i.message_sent IS TRUE AND i.message_sent_at IS NOT NULL AND i.breakdown->>'category'='commission' AND i.breakdown->>'ledger_id'=l.id::text AND i.breakdown->'approved_intent'=intent)<>1 THEN RAISE EXCEPTION 'approved_agent_adjustment_paid_document_unverified' USING ERRCODE='23514';END IF;
  RETURN jsonb_build_object('success',true,'replayed',true,'adjustment_id',a.id,'ledger_id',l.id,'club_id',p_club,'user_id',a.target_id,'amount',a.amount,'bank_before',l.pre_from_balance,'bank_after',l.post_from_balance,'wallet_before',l.pre_to_balance,'wallet_after',l.post_to_balance,'approved_intent_md5',md5(intent::text));
 END IF;
 IF a.status<>'approved' OR n<>0 THEN RAISE EXCEPTION 'approved_agent_adjustment_not_unsettled_approved' USING ERRCODE='23514';END IF;
 IF public.fn_platform_frozen() IS DISTINCT FROM false THEN RAISE EXCEPTION 'approved_agent_adjustment_platform_frozen' USING ERRCODE='55006';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('cashier-agent-authority:'||p_club||':'||a.target_id,0));
 SELECT chip_treasury INTO STRICT bank_before FROM public.clubs WHERE id=p_club FOR NO KEY UPDATE;
 SELECT*INTO STRICT g FROM public.agents WHERE club_id=p_club AND user_id=a.target_id FOR NO KEY UPDATE;
 wallet_before:=g.agent_wallet_balance;
 IF (g.status IS NULL OR g.status NOT IN('active','suspended')) OR g.role IS NULL OR g.role NOT IN('super_agent','agent','sub_agent') OR wallet_before IS NULL OR wallet_before<0 OR wallet_before<>round(wallet_before,2) OR wallet_before::text IN('NaN','Infinity','-Infinity') OR g.business_balance IS DISTINCT FROM wallet_before THEN RAISE EXCEPTION 'approved_agent_adjustment_agent_wallet_invalid' USING ERRCODE='23514';END IF;
 IF bank_before IS NULL OR bank_before<a.amount OR bank_before<>round(bank_before,2) OR bank_before::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'approved_agent_adjustment_bank_funding_shortfall' USING ERRCODE='23514';END IF;
 SELECT jsonb_object_agg(k,coalesce(current_setting(k,true),''))INTO saved FROM unnest(ARRAY['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_counterparty_label','app.ledger_settlement','app.ledger_idempotency_key','app.ledger_correlation','app.ledger_autoskip_clubs','app.ledger_autoskip_agents','app.ledger_hand_id','app.ledger_tournament_id'])k;
 PERFORM public.fn_ca_declare_ledger('commission','club_treasury',p_club,p_adjustment,key,ARRAY['clubs','agents']);
 PERFORM set_config('app.ledger_correlation',a.id::text,true);PERFORM set_config('app.ledger_hand_id','',true);PERFORM set_config('app.ledger_tournament_id','',true);
 UPDATE public.clubs SET chip_treasury=chip_treasury-a.amount,updated_at=now()WHERE id=p_club AND chip_treasury=bank_before RETURNING chip_treasury INTO bank_after;
 UPDATE public.agents SET agent_wallet_balance=agent_wallet_balance+a.amount,updated_at=now()WHERE id=g.id AND agent_wallet_balance=wallet_before RETURNING agent_wallet_balance INTO wallet_after;
 IF bank_after IS NULL OR wallet_after IS NULL OR bank_before-bank_after<>a.amount OR wallet_after-wallet_before<>a.amount OR NOT EXISTS(SELECT FROM public.agents WHERE id=g.id AND agent_wallet_balance=wallet_after AND business_balance=wallet_after)THEN RAISE EXCEPTION 'approved_agent_adjustment_transfer_not_conserved' USING ERRCODE='23514';END IF;
 INSERT INTO public.chip_ledger(performed_by,from_type,from_entity_id,to_type,to_entity_id,amount,category,club_id,description,idempotency_key,correlation_id,metadata,pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
 -- Same existing real platform journal attribution used by original R2.
 -- This is automated postgres execution, not a human cashier session.
 VALUES('2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid,'club_treasury',p_club,'agent_wallet',a.target_id,a.amount,'commission',p_club,a.reason,key,a.id,jsonb_build_object('adjustment_id',a.id,'approved_intent',intent,'approved_intent_md5',md5(intent::text),'approved_actor',a.actor,'approved_by',a.approver,'executed_by_db_role',current_user,'executed_by_session_user',session_user,'executor_application',current_setting('application_name',true),'paid_to','agent_wallet','platform_error_absorbed',true),bank_before,bank_after,wallet_before,wallet_after)RETURNING*INTO l;
 IF l.status IS DISTINCT FROM 'posted' OR l.amount IS DISTINCT FROM a.amount OR l.idempotency_key IS DISTINCT FROM key OR l.performed_by IS DISTINCT FROM '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid OR l.metadata->>'approved_actor'IS DISTINCT FROM a.actor::text OR l.metadata->>'approved_by'IS DISTINCT FROM a.approver::text OR l.metadata->>'paid_to'IS DISTINCT FROM 'agent_wallet' OR l.metadata->>'executed_by_db_role'IS DISTINCT FROM 'postgres' OR l.metadata->>'executed_by_session_user'IS DISTINCT FROM 'postgres' OR l.metadata->'approved_intent'IS DISTINCT FROM intent OR l.pre_from_balance-l.post_from_balance IS DISTINCT FROM a.amount OR l.post_to_balance-l.pre_to_balance IS DISTINCT FROM a.amount THEN RAISE EXCEPTION 'approved_agent_adjustment_journal_receipt_invalid' USING ERRCODE='23514';END IF;
  IF l.category='commission' AND (SELECT count(*) FROM public.settlement_invoices i WHERE i.source_ledger_id=l.id AND i.club_id=p_club AND i.invoice_type='club_to_agent' AND i.from_entity_type='club' AND i.from_entity_id=p_club::text AND i.to_entity_type='agent' AND i.to_entity_id=a.target_id::text AND i.gross_amount=a.amount AND i.net_amount=a.amount AND i.deductions=0 AND i.status='paid' AND i.chips_transferred IS TRUE AND i.transferred_at=l.created_at AND i.invoice_number IS NOT NULL AND i.message_sent IS TRUE AND i.message_sent_at IS NOT NULL AND i.breakdown->>'category'='commission' AND i.breakdown->>'ledger_id'=l.id::text AND i.breakdown->'approved_intent'=intent)<>1 THEN RAISE EXCEPTION 'approved_agent_adjustment_paid_document_unverified' USING ERRCODE='23514';END IF;
 UPDATE public.ca_manual_adjustments SET status='settled'WHERE id=a.id AND status='approved';GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'approved_agent_adjustment_status_transition_lost';END IF;
 FOR setting IN SELECT jsonb_object_keys(saved)LOOP PERFORM set_config(setting,saved->>setting,true);END LOOP;
 RETURN jsonb_build_object('success',true,'replayed',false,'adjustment_id',a.id,'ledger_id',l.id,'club_id',p_club,'user_id',a.target_id,'amount',a.amount,'bank_before',bank_before,'bank_after',bank_after,'wallet_before',wallet_before,'wallet_after',wallet_after,'approved_intent_md5',md5(intent::text));
END $function$

public.fn_process_credit_invoice_payment.def:
CREATE OR REPLACE FUNCTION public.fn_process_credit_invoice_payment(p_invoice_id uuid, p_amount numeric, p_method text, p_operation_id uuid, p_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE inv public.credit_invoices%ROWTYPE; agent public.agents%ROWTYPE; pay public.credit_payments%ROWTYPE;
 actor uuid:=auth.uid(); engine boolean:=public.fn_caller_is_engine(); remaining numeric; old_club text; deducted boolean; new_status text; tracking boolean; bank numeric; ctx jsonb; setting_key text;
BEGIN
 IF p_invoice_id IS NULL OR p_operation_id IS NULL OR p_amount IS NULL OR p_amount<=0
    OR p_amount::text IN('NaN','Infinity','-Infinity') OR p_amount<>round(p_amount,2)
 THEN RETURN jsonb_build_object('ok',false,'success',false,'reason','invalid_payment'); END IF;
 IF p_method IS NULL OR p_method NOT IN('wallet','external') THEN
   RETURN jsonb_build_object('ok',false,'success',false,'reason','unsupported_payment_method'); END IF;
 SELECT * INTO inv FROM public.credit_invoices WHERE id=p_invoice_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'success',false,'reason','invoice_not_found'); END IF;
 SELECT * INTO agent FROM public.agents WHERE id=inv.agent_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'success',false,'reason','agent_user_not_found'); END IF;
 IF p_method='wallet' THEN
   -- A service credential is not authority to spend an arbitrary user's wallet.
   IF actor IS NULL OR actor<>agent.user_id THEN
    RAISE EXCEPTION 'not_your_wallet' USING ERRCODE='42501'; END IF;
 ELSE
   IF NOT engine AND (actor IS NULL OR NOT (public.fn_is_club_admin_uid(agent.club_id) OR public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'only_receiving_club_can_record_external_payment' USING ERRCODE='42501'; END IF;
   IF NULLIF(btrim(p_reference),'') IS NULL OR length(p_reference)>256 THEN
    RETURN jsonb_build_object('ok',false,'success',false,'reason','payment_reference_required'); END IF;
 END IF;
 SELECT EXISTS(SELECT FROM public.agent_credit_weekly_basis b WHERE b.agent_id=inv.agent_id AND b.period_end=inv.period_end) INTO tracking;
 IF tracking THEN PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||agent.club_id::text,0)); END IF;
 -- Use the same agent -> invoice lock order as invoice generation.
 SELECT * INTO agent FROM public.agents WHERE id=inv.agent_id FOR UPDATE;
 SELECT * INTO inv FROM public.credit_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF inv.agent_id IS DISTINCT FROM agent.id OR agent.club_id IS NULL
   OR (p_method='wallet' AND actor IS DISTINCT FROM agent.user_id)
   OR (p_method='external' AND NOT engine AND NOT (public.fn_is_club_admin_uid(agent.club_id) OR public.fn_is_platform_admin()))
 THEN RAISE EXCEPTION 'credit_account_changed' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('credit_payment:'||p_operation_id::text,0));
 SELECT * INTO pay FROM public.credit_payments WHERE operation_id=p_operation_id;
 IF NOT FOUND AND p_method='external' THEN
   SELECT * INTO pay FROM public.credit_payments WHERE invoice_id=p_invoice_id AND payment_method='external' AND payment_reference=btrim(p_reference);
 END IF;
 IF pay.id IS NOT NULL THEN
   IF pay.invoice_id<>p_invoice_id OR pay.amount<>p_amount OR pay.payment_method<>p_method
      OR pay.payer_user_id IS DISTINCT FROM actor OR pay.payment_reference IS DISTINCT FROM NULLIF(btrim(p_reference),'')
   THEN RETURN jsonb_build_object('ok',false,'success',false,'reason','operation_conflict'); END IF;
   RETURN jsonb_build_object('ok',true,'success',true,'duplicate',true,'amount',pay.amount,'applied',pay.amount,
     'invoice_id',inv.id,'status',inv.status,'amount_remaining',inv.amount_remaining,'payment',to_jsonb(pay));
 END IF;
 IF inv.status NOT IN('pending','partial','overdue') THEN
   RETURN jsonb_build_object('ok',false,'success',false,'reason',CASE inv.status WHEN 'void' THEN 'invoice_voided' WHEN 'paid' THEN 'already_settled' ELSE 'invoice_not_payable' END);
 END IF;
 IF inv.debt_owed IS NULL OR inv.amount_paid IS NULL OR inv.amount_remaining IS NULL OR agent.credit_used IS NULL
   OR inv.debt_owed::text IN('NaN','Infinity','-Infinity') OR inv.amount_paid::text IN('NaN','Infinity','-Infinity')
   OR inv.amount_remaining::text IN('NaN','Infinity','-Infinity') OR agent.credit_used::text IN('NaN','Infinity','-Infinity')
   OR inv.debt_owed<>round(inv.debt_owed,2) OR inv.amount_paid<>round(inv.amount_paid,2)
   OR agent.credit_used<>round(agent.credit_used,2) OR inv.amount_paid<0 OR agent.credit_used<0
   OR inv.amount_remaining<>inv.debt_owed-inv.amount_paid
 THEN RAISE EXCEPTION 'credit_balance_evidence_invalid' USING ERRCODE='23514'; END IF;
 remaining:=inv.amount_remaining;
 IF p_amount>remaining THEN RETURN jsonb_build_object('ok',false,'success',false,'reason','amount_exceeds_remaining','amount_remaining',remaining); END IF;
 IF NOT tracking AND p_amount>agent.credit_used THEN RAISE EXCEPTION 'credit_invoice_exceeds_drawn_debt' USING ERRCODE='23514'; END IF;
 IF tracking THEN
   IF agent.agent_wallet_balance IS NULL OR agent.agent_wallet_balance::text IN('NaN','Infinity','-Infinity') OR agent.agent_wallet_balance<0 OR agent.agent_wallet_balance<>round(agent.agent_wallet_balance,2) THEN RAISE EXCEPTION 'invalid_agent_wallet' USING ERRCODE='23514'; END IF;
   SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),'')) INTO ctx FROM unnest(ARRAY['app.ledger_club_id','app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_counterparty_label','app.ledger_idempotency_key','app.ledger_settlement','app.ledger_autoskip_agents','app.ledger_autoskip_clubs','app.ledger_autoskip_club_members','app.ledger_tournament','app.ledger_correlation']) k;
   PERFORM set_config('app.ledger_tournament','',true);
   PERFORM set_config('app.ledger_settlement','',true);
   PERFORM set_config('app.ledger_correlation',p_operation_id::text,true);
   PERFORM public.fn_ca_declare_ledger(CASE WHEN p_method='wallet' THEN 'transfer' ELSE 'club_bank_send' END,'agent_wallet',agent.user_id,NULL,'agent-credit-payment:'||p_operation_id::text,ARRAY['agents']);
   PERFORM set_config('app.ledger_club_id',agent.club_id::text,true);
   PERFORM set_config('app.ledger_autoskip_club_members','0',true);
   PERFORM set_config('app.ledger_autoskip_clubs','0',true);
   IF p_method='wallet' THEN
    deducted:=public.atomic_deduct_wallet_and_log(agent.user_id,p_amount,'settlement','Agent Wallet Top-Up: '||p_invoice_id::text,NULL,NULL,p_invoice_id);
    IF deducted IS DISTINCT FROM true THEN
     FOR setting_key IN SELECT jsonb_object_keys(ctx) LOOP PERFORM set_config(setting_key,ctx->>setting_key,true); END LOOP;
     RETURN jsonb_build_object('ok',false,'success',false,'reason','insufficient_balance');
    END IF;
   ELSE
    SELECT chip_treasury INTO bank FROM public.clubs WHERE id=agent.club_id FOR UPDATE;
    IF bank IS NULL OR bank::text IN('NaN','Infinity','-Infinity') OR bank<>round(bank,2) OR bank<p_amount THEN
     FOR setting_key IN SELECT jsonb_object_keys(ctx) LOOP PERFORM set_config(setting_key,ctx->>setting_key,true); END LOOP;
     RETURN jsonb_build_object('ok',false,'success',false,'reason','insufficient_club_bank');
    END IF;
    UPDATE public.clubs SET chip_treasury=chip_treasury-p_amount WHERE id=agent.club_id;
   END IF;
   UPDATE public.agents SET agent_wallet_balance=agent_wallet_balance+p_amount,updated_at=now() WHERE id=agent.id;
   FOR setting_key IN SELECT jsonb_object_keys(ctx) LOOP PERFORM set_config(setting_key,ctx->>setting_key,true); END LOOP;
 ELSIF p_method='wallet' THEN
   old_club:=current_setting('app.ledger_club_id',true);
   PERFORM set_config('app.ledger_club_id',agent.club_id::text,true);
   deducted:=public.atomic_deduct_wallet_and_log(agent.user_id,p_amount,'settlement','Credit Invoice Payment: '||p_invoice_id::text,NULL,NULL,p_invoice_id);
   PERFORM set_config('app.ledger_club_id',COALESCE(old_club,''),true);
   IF deducted IS DISTINCT FROM true THEN RETURN jsonb_build_object('ok',false,'success',false,'reason','insufficient_balance'); END IF;
 END IF;
 remaining:=remaining-p_amount;
 new_status:=CASE WHEN remaining=0 THEN 'paid' ELSE 'partial' END;
 UPDATE public.credit_invoices SET amount_paid=amount_paid+p_amount,amount_remaining=remaining,status=new_status,
  paid_at=CASE WHEN remaining=0 THEN now() ELSE paid_at END WHERE id=p_invoice_id;
 IF NOT tracking THEN UPDATE public.agents SET credit_used=credit_used-p_amount,updated_at=now() WHERE id=agent.id; END IF;
 INSERT INTO public.credit_payments(invoice_id,amount,payment_method,transaction_id,operation_id,payer_user_id,payment_reference)
  VALUES(p_invoice_id,p_amount,p_method,p_operation_id::text,p_operation_id,actor,NULLIF(btrim(p_reference),'')) RETURNING * INTO pay;
 -- The existing payment trigger creates the invoice and both delivery receipts.
 UPDATE public.settlement_invoices SET status=CASE WHEN remaining=0 THEN 'paid' ELSE 'generated' END,updated_at=now()
  WHERE source_credit_invoice_id=p_invoice_id;
 RETURN jsonb_build_object('ok',true,'success',true,'duplicate',false,'amount',p_amount,'applied',p_amount,
  'invoice_id',p_invoice_id,'status',new_status,'amount_remaining',remaining,'credit_used_after',CASE WHEN tracking THEN agent.credit_used ELSE agent.credit_used-p_amount END,'payment',to_jsonb(pay));
END $function$

public.fn_cashier_player_wallet_send(p_c.def:
CREATE OR REPLACE FUNCTION public.fn_cashier_player_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid(); actor_role text; target_role text; gate jsonb; result jsonb; before_balance numeric; after_balance numeric; target_after numeric; agent_id uuid; tx uuid; context jsonb; setting text;
BEGIN
 gate:=public.fn_cashier_exact_intent_begin('cashier_player_send',p_club_id,p_op_id,jsonb_build_object('actor',actor,'club',p_club_id,'action','cashier_player_send','target',p_to_user_id,'amount',p_amount,'destination',p_destination,'reason',p_reason));
 IF gate->>'state'='return' THEN RETURN gate->'response'; END IF;
 IF p_club_id IS NULL OR p_to_user_id IS NULL OR p_amount IS NULL OR p_amount<=0 OR p_amount>1e9 OR p_amount<>round(p_amount,2) THEN RETURN jsonb_build_object('success',false,'error','Enter A Valid Send Amount And Recipient'); END IF;
 IF p_destination IS NULL OR p_destination NOT IN ('player_wallet','agent_wallet','promo_wallet') THEN RETURN jsonb_build_object('success',false,'error','Unknown Destination Wallet'); END IF;
 IF actor=p_to_user_id AND p_destination='player_wallet' THEN RETURN jsonb_build_object('success',false,'error','Choose A Different Wallet'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));
 PERFORM 1 FROM public.clubs WHERE id=p_club_id FOR UPDATE;
 PERFORM 1 FROM public.club_members WHERE club_id=p_club_id AND user_id IN (actor,p_to_user_id) ORDER BY user_id FOR UPDATE;
 actor_role:=public.fn_club_bank_role(p_club_id);
 IF actor_role IS NULL OR actor_role NOT IN ('owner','co_owner','super_agent','agent','sub_agent') THEN RETURN jsonb_build_object('success',false,'error','Your Cashier Authority Is No Longer Active'); END IF;
 IF actor<>p_to_user_id AND NOT public.fn_club_cashier_can_transact(p_club_id,actor,p_to_user_id) THEN RETURN jsonb_build_object('success',false,'error','That Member Is Not In Your Downline'); END IF;
 SELECT role INTO target_role FROM public.club_members WHERE club_id=p_club_id AND user_id=p_to_user_id AND coalesce(status,'active') IN ('active','approved');
 IF target_role IS NULL THEN RETURN jsonb_build_object('success',false,'error','Recipient Is Not An Active Member Of This Club'); END IF;
 IF (p_destination='player_wallet' AND target_role='admin') OR (p_destination<>'player_wallet' AND target_role NOT IN ('owner','co_owner','admin','super_agent','agent','sub_agent')) THEN RETURN jsonb_build_object('success',false,'error','Recipient Does Not Hold That Wallet'); END IF;
 SELECT coalesce(chip_balance,0) INTO before_balance FROM public.club_members WHERE club_id=p_club_id AND user_id=actor;
 IF before_balance IS NULL OR before_balance<p_amount THEN RETURN jsonb_build_object('success',false,'error','Insufficient Player Wallet Balance'); END IF;
 SELECT jsonb_object_agg(k,coalesce(current_setting(k,true),'')) INTO context FROM unnest(ARRAY['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_counterparty_label','app.ledger_correlation','app.ledger_idempotency_key','app.ledger_autoskip_agents','app.ledger_autoskip_club_members','app.ledger_tournament','app.ledger_settlement']) settings(k);
 PERFORM set_config('app.ledger_tournament','',true);
 PERFORM set_config('app.ledger_settlement','',true);
 PERFORM public.fn_ca_declare_ledger('transfer','player_wallet',actor,NULL,'cashier_player_send:'||p_op_id::text,ARRAY['club_members','agents']);
 PERFORM set_config('app.ledger_correlation',p_op_id::text,true);
 UPDATE public.club_members SET chip_balance=coalesce(chip_balance,0)-p_amount,updated_at=now() WHERE club_id=p_club_id AND user_id=actor RETURNING chip_balance INTO after_balance;
 IF p_destination='player_wallet' THEN
  UPDATE public.club_members SET chip_balance=coalesce(chip_balance,0)+p_amount,updated_at=now() WHERE club_id=p_club_id AND user_id=p_to_user_id RETURNING chip_balance INTO target_after;
 ELSE
  agent_id:=public.fn_ensure_agent_row(p_club_id,p_to_user_id,target_role);
  IF p_destination='agent_wallet' THEN UPDATE public.agents SET agent_wallet_balance=coalesce(agent_wallet_balance,0)+p_amount,updated_at=now() WHERE id=agent_id RETURNING agent_wallet_balance INTO target_after;
  ELSE UPDATE public.agents SET promo_wallet_balance=coalesce(promo_wallet_balance,0)+p_amount,updated_at=now() WHERE id=agent_id RETURNING promo_wallet_balance INTO target_after; END IF;
 END IF;
 IF target_after IS NULL THEN RAISE EXCEPTION 'Recipient Credit Landed Nowhere'; END IF;
 PERFORM set_config('app.ledger_idempotency_key','',true);
 IF NOT public.fn_ca_post_leg('transfer','player_wallet',actor,p_destination,p_to_user_id,p_amount,p_club_id,'cashier_player_send:'||p_op_id::text,'Cashier Send From Player Wallet') THEN RAISE EXCEPTION 'The Transfer Journal Was Not Written'; END IF;
 FOR setting IN SELECT jsonb_object_keys(context) LOOP PERFORM set_config(setting,context->>setting,true); END LOOP;
 INSERT INTO public.chip_transactions(club_id,from_user_id,to_user_id,amount,transaction_type,notes,metadata,balance_after) VALUES(p_club_id,actor,p_to_user_id,p_amount,'peer_transfer',coalesce(p_reason,'Cashier Send Out'),jsonb_build_object('op_id',p_op_id,'source','player_wallet','destination',p_destination,'player_wallet_after',after_balance,'recipient_balance_after',target_after),after_balance) RETURNING id INTO tx;
 result:=jsonb_build_object('success',true,'replayed',false,'transaction_id',tx,'amount',p_amount,'source','player_wallet','destination',p_destination,'player_wallet_after',after_balance,'recipient_balance_after',target_after);
 RETURN public.fn_cashier_exact_intent_finish(p_op_id,result);
END
$function$

public.fn_agent_wallet_claim_back_phase2.def:
CREATE OR REPLACE FUNCTION public.fn_agent_wallet_claim_back_phase2_core_20260831(p_club_id uuid, p_transaction_id uuid, p_amount numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_setting text;
  v_actor            uuid := auth.uid();
  v_op_id            uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior            record;
  v_src              record;
  v_claimed          numeric;
  v_claimed_after    numeric;
  v_remaining_exact  numeric;
  v_remaining        numeric;
  v_take             numeric;
  v_complete         boolean;
  v_dest             text;
  v_held             numeric;
  v_agent_id         uuid;
  v_float_after      numeric;
  v_holder_after     numeric;
  v_tx_id            uuid;
  v_drawn            numeric;
  v_repaid           numeric;
  v_repay            numeric := 0;
  v_my_agent_id      uuid;
  v_my_used          numeric;
  v_credit_after     numeric; v_destination_after numeric;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;
  if p_club_id is null or p_transaction_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recent Agent Wallet Send');
  end if;
  if p_amount is not null and
     (p_amount <= 0 or p_amount > 1e9 or p_amount <> round(p_amount, 2)) then
    return jsonb_build_object(
      'success', false,
      'error', 'Claim Back Amounts Must Be Positive Whole Cents');
  end if;

  -- One caller/op pair is serialized, so two simultaneous retries cannot both
  -- pass the replay read and enter the money section.
  perform pg_advisory_xact_lock(hashtextextended(
    'agent-wallet-claim:' || p_club_id::text || ':' || v_actor::text || ':' || v_op_id::text,
    0
  ));

  select id, amount, metadata into v_prior
    from public.chip_transactions
   where club_id = p_club_id
     and transaction_type = 'agent_wallet_claim_back'
     and to_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    if coalesce(v_prior.metadata ->> 'original_transaction_id', '')
         is distinct from p_transaction_id::text
       or (p_amount is not null and v_prior.amount is distinct from p_amount) then
      return jsonb_build_object(
        'success', false,
        'error', 'That Retry Key Belongs To A Different Claim Back');
    end if;
    return jsonb_build_object(
      'success', true,
      'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'agent_wallet_after', (v_prior.metadata ->> 'agent_wallet_after')::numeric,
      'credit_repaid', coalesce((v_prior.metadata ->> 'credit_repaid')::numeric, 0),
      'credit_used_after', (v_prior.metadata ->> 'credit_used_after')::numeric);
  end if;

  select * into v_src
    from public.chip_transactions
   where id = p_transaction_id
     and club_id = p_club_id
   for update;
  if v_src is null then
    return jsonb_build_object('success', false, 'error', 'That Send Could Not Be Found');
  end if;
  if v_src.transaction_type <> 'agent_wallet_send' then
    return jsonb_build_object(
      'success', false,
      'error', 'Only An Agent Wallet Send Can Be Claimed Back This Way');
  end if;
  if v_src.from_user_id is distinct from v_actor then
    return jsonb_build_object(
      'success', false,
      'error', 'You Can Only Claim Back Chips You Sent Yourself');
  end if;
  if coalesce(v_src.is_reversed, false) then
    return jsonb_build_object('success', false, 'error', 'That Send Has Already Been Claimed Back');
  end if;
  if v_src.reversible_until is null or now() > v_src.reversible_until then
    return jsonb_build_object(
      'success', false,
      'error', 'The Ten Minute Window To Claim These Chips Back Has Closed. '
               || 'The Player Must Request A Cash Out Instead');
  end if;

  v_claimed := coalesce((v_src.metadata ->> 'claimed_back')::numeric, 0);
  v_remaining_exact := greatest(v_src.amount - v_claimed, 0);

  -- Round DOWN, never to nearest. A historical 9.9951 remainder can safely
  -- return 9.99; rounding it to 10.00 would create another 0.0049 chips.
  v_remaining := trunc(v_remaining_exact, 2);
  if v_remaining < 0.01 then
    return jsonb_build_object('success', false, 'error', 'That Send Has Already Been Claimed Back');
  end if;

  -- Null means all safely claimable whole cents. This is what the cashier uses
  -- so contaminated historical rows can be closed without echoing sub-cents.
  v_take := coalesce(p_amount, v_remaining);
  if v_take > v_remaining then
    return jsonb_build_object(
      'success', false,
      'error', 'Only ' || trim(to_char(v_remaining, 'FM999,999,999,990.00'))
               || ' Chips Of That Send Are Left To Claim Back',
      'remaining', v_remaining,
      'requested', v_take);
  end if;

  v_claimed_after := v_claimed + v_take;
  v_complete := (v_src.amount - v_claimed_after) < 0.01;

  v_dest := coalesce(v_src.metadata ->> 'destination', 'player_wallet');
  if v_dest = 'player_wallet' then
    select coalesce(chip_balance, 0) into v_held
      from public.club_members
     where club_id = p_club_id and user_id = v_src.to_user_id
     for update;
  else
    select a.id, case when v_dest = 'promo_wallet' then coalesce(a.promo_wallet_balance, 0) else coalesce(a.agent_wallet_balance, 0) end into v_agent_id, v_held
      from public.agents a
     where a.club_id = p_club_id and a.user_id = v_src.to_user_id
     for update;
  end if;

  if v_held is null then
    return jsonb_build_object(
      'success', false,
      'error', 'That Wallet Could Not Be Read, So Nothing Was Moved');
  end if;
  if v_held < v_take then
    return jsonb_build_object(
      'success', false,
      'error', 'Those Chips Have Already Been Spent. That Wallet Only Holds '
               || trim(to_char(v_held, 'FM999,999,999,990.00')) || ' Chips',
      'held', v_held,
      'requested', v_take);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): a claim back is ONE `agent_claim` row from
  -- the wallet that held the send back to the agent's float, keyed and
  -- correlated on the op. The agents trigger is skipped for both float
  -- writes: a player holder's club_members trigger writes the row with the
  -- agent's float as counterparty; an agent holder (both sides in `agents`)
  -- gets the row posted explicitly below. The share that repays the credit
  -- line never reaches the float, so it is its own `credit_repayment
  -- agent_wallet -> credit_facility` row. Never a refusal.
  select jsonb_object_agg(k,coalesce(current_setting(k,true),'')) into v_context
   from unnest(array['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_tournament','app.ledger_settlement','app.ledger_idempotency_key','app.ledger_correlation','app.ledger_autoskip_agents']) settings(k);
  perform set_config('app.ledger_tournament','',true);
  perform set_config('app.ledger_settlement','',true);
  perform public.fn_ca_declare_ledger('agent_claim', CASE WHEN v_dest='promo_wallet' THEN 'promo_wallet' ELSE 'agent_wallet' END, v_actor, null,
    'agent_claim:' || v_op_id::text, array['agents']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  if v_dest = 'player_wallet' then
    update public.club_members
       set chip_balance = coalesce(chip_balance, 0) - v_take,
           updated_at = now()
     where club_id = p_club_id and user_id = v_src.to_user_id
     returning chip_balance into v_holder_after;
  else
    if v_dest = 'promo_wallet' then
      update public.agents set promo_wallet_balance = coalesce(promo_wallet_balance, 0) - v_take, updated_at = now()
       where id = v_agent_id returning promo_wallet_balance into v_holder_after;
    else
      update public.agents set agent_wallet_balance = coalesce(agent_wallet_balance, 0) - v_take, updated_at = now()
       where id = v_agent_id returning agent_wallet_balance into v_holder_after;
    end if;
    perform set_config('app.ledger_idempotency_key', '', true);
    perform public.fn_ca_post_leg('agent_claim', v_dest, v_src.to_user_id, CASE WHEN v_dest='promo_wallet' THEN 'promo_wallet' ELSE 'agent_wallet' END, v_actor,
      v_take, p_club_id, 'agent_claim:' || v_op_id::text,
      'Agent wallet claim back from a downline agent wallet (fn_agent_wallet_claim_back_phase2_core_20260831)');
  end if;

  -- HOW MUCH OF THIS CLAIM IS A REPAYMENT.
  --
  -- credit_drawn is what this send borrowed; credit_repaid is how much of that
  -- borrowing earlier partial claims have already handed back. The share of a
  -- partial claim is proportional, truncated down so repeated partials can
  -- never repay more than was drawn. The final claim settles the exact
  -- remainder, so truncation cannot strand a cent of debt on a send that has
  -- been returned in full.
  v_drawn  := coalesce((v_src.metadata ->> 'credit_drawn')::numeric, 0);
  v_repaid := coalesce((v_src.metadata ->> 'credit_repaid')::numeric, 0);

  select a.id, coalesce(a.credit_used, 0) into v_my_agent_id, v_my_used
    from public.agents a
   where a.club_id = p_club_id and a.user_id = v_actor
   for update;
  if v_my_agent_id is null then
    raise exception 'agent wallet row vanished for % in club %', v_actor, p_club_id;
  end if;

  if v_drawn > 0 and v_dest <> 'promo_wallet' then
    if v_complete then
      v_repay := greatest(v_drawn - v_repaid, 0);
    else
      v_repay := least(trunc(v_drawn * v_take / v_src.amount, 2),
                       greatest(v_drawn - v_repaid, 0));
    end if;
    -- The debt may already have been settled another way: an invoice paid
    -- inside the ten minute window pays credit_used down (phase 1), and paying
    -- twice for the same borrowing would hand the agent free chips.
    v_repay := greatest(least(v_repay, v_my_used), 0);
  end if;

  if v_repay > 0 then
    perform public.fn_ca_post_leg('credit_repayment', 'agent_wallet', v_actor, 'credit_facility', v_actor,
      v_repay, p_club_id, 'agent_claim:credit:' || v_op_id::text,
      'Claimed back chips repay the credit line drawn for the send (fn_agent_wallet_claim_back_phase2_core_20260831)');
  end if;

  -- Every chip returns: what is not repaying a debt becomes float.
  update public.agents
     set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + CASE WHEN v_dest='promo_wallet' THEN 0 ELSE (v_take-v_repay) END, promo_wallet_balance = coalesce(promo_wallet_balance,0) + CASE WHEN v_dest='promo_wallet' THEN v_take ELSE 0 END,
         credit_used          = greatest(coalesce(credit_used, 0) - v_repay, 0),
         updated_at = now()
   where id = v_my_agent_id
   returning agent_wallet_balance, credit_used, CASE WHEN v_dest='promo_wallet' THEN promo_wallet_balance ELSE agent_wallet_balance END into v_float_after, v_credit_after, v_destination_after;
  for v_setting in select jsonb_object_keys(v_context) loop
    perform set_config(v_setting,v_context->>v_setting,true);
  end loop;

  update public.chip_transactions
     set metadata = coalesce(metadata, '{}'::jsonb)
                    || jsonb_build_object('claimed_back', v_claimed_after,
                                          'credit_repaid', v_repaid + v_repay),
         is_reversed = v_complete,
         clawed_back = v_complete
   where id = v_src.id;

  insert into public.chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, v_src.to_user_id, v_actor, v_take, 'agent_wallet_claim_back',
     coalesce(nullif(btrim(p_reason), ''), 'Agent Wallet Claim Back Inside The Ten Minute Window'),
     jsonb_build_object(
       'op_id', v_op_id,
       'source', v_dest, 'destination', CASE WHEN v_dest='promo_wallet' THEN 'promo_wallet' ELSE 'agent_wallet' END,
       'original_transaction_id', v_src.id,
       'holder_balance_after', v_holder_after,
       'agent_wallet_after', v_float_after, 'destination_balance_after', v_destination_after,
       'credit_repaid', v_repay,
       'credit_used_after', v_credit_after),
     v_destination_after)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true,
    'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', v_take,
    'source', v_dest, 'destination', CASE WHEN v_dest='promo_wallet' THEN 'promo_wallet' ELSE 'agent_wallet' END,
    'holder_balance_after', v_holder_after,
    'agent_wallet_after', v_float_after, 'destination_balance_after', v_destination_after,
    'credit_repaid', v_repay,
    'credit_used_after', v_credit_after);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from public.chip_transactions
     where club_id = p_club_id
       and transaction_type = 'agent_wallet_claim_back'
       and to_user_id = v_actor
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    if v_prior.id is null then
      raise;
    end if;
    if coalesce(v_prior.metadata ->> 'original_transaction_id', '')
         is distinct from p_transaction_id::text
       or (p_amount is not null and v_prior.amount is distinct from p_amount) then
      return jsonb_build_object(
        'success', false,
        'error', 'That Retry Key Belongs To A Different Claim Back');
    end if;
    return jsonb_build_object(
      'success', true,
      'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'agent_wallet_after', (v_prior.metadata ->> 'agent_wallet_after')::numeric,
      'credit_repaid', coalesce((v_prior.metadata ->> 'credit_repaid')::numeric, 0),
      'credit_used_after', (v_prior.metadata ->> 'credit_used_after')::numeric);
end
$function$

public.fn_club_promo_send_core_20261004(.def:
CREATE OR REPLACE FUNCTION public.fn_club_promo_send_core_20261004(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_dest         text := lower(coalesce(p_destination, 'player_wallet'));
  v_op_id        uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior        record;
  v_pot_before   numeric;
  v_pot_after    numeric;
  v_to_role      text;
  v_to_after     numeric;
  v_agent_id     uuid;
  v_tx_id        uuid;
begin
  IF p_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
  END IF;
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner Or Admin May Send From The Club Promo Wallet');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false, 'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  end if;
  if v_dest not in ('player_wallet', 'agent_wallet', 'cashier_agent_wallet', 'cashier_promo_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Destination Wallet');
  end if;
  if p_to_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recipient');
  end if;

  select coalesce(c.promo_balance, 0) into v_pot_before
    from clubs c where c.id = p_club_id for update;
  if v_pot_before is null then
    return jsonb_build_object('success', false, 'error', 'Club Not Found');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'club_promo_send'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'pot_after', (v_prior.metadata ->> 'pot_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
  end if;

  if v_pot_before < p_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient Club Promo Wallet Balance',
      'balance', v_pot_before, 'requested', p_amount);
  end if;

  select cm.role into v_to_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_to_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_to_role is null then
    return jsonb_build_object('success', false, 'error', 'Recipient Is Not An Active Member Of This Club');
  end if;
  if v_dest in ('agent_wallet', 'cashier_agent_wallet', 'cashier_promo_wallet')
     and v_to_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false, 'error', 'Only Staff Or Agents Hold A Promo Wallet');
  end if;
  if v_dest = 'player_wallet' and v_to_role = 'admin' then
    return jsonb_build_object('success', false, 'error', 'An Admin Does Not Hold A Player Wallet');
  end if;
  if p_to_user_id <> v_actor
     and not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_to_user_id) then
    return jsonb_build_object('success', false, 'error', 'That Member Is Not In Your Downline');
  end if;

  perform public.fn_ca_declare_ledger('promo_send', 'promo_wallet', p_club_id, null,
    'club_promo_send:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_counterparty_label', 'clubs.promo_balance', true);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  update clubs
     set promo_balance = coalesce(promo_balance, 0) - p_amount,
         updated_at = now()
   where id = p_club_id
   returning promo_balance into v_pot_after;

  if v_dest = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;
  else
    v_agent_id := public.fn_ensure_agent_row(p_club_id, p_to_user_id, v_to_role);
    if v_agent_id is null then
      raise exception 'could not ensure agents row for % in club %', p_to_user_id, p_club_id;
    end if;
    if v_dest = 'cashier_agent_wallet' then
      update agents set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + p_amount, updated_at = now()
       where id = v_agent_id returning agent_wallet_balance into v_to_after;
    else
      update agents set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount, updated_at = now()
       where id = v_agent_id returning promo_wallet_balance into v_to_after;
    end if;
  end if;
  if v_to_after is null then
    raise exception 'club promo credit landed nowhere for % in %', p_to_user_id, p_club_id;
  end if;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, v_actor, p_to_user_id, p_amount, 'club_promo_send',
     coalesce(nullif(btrim(p_reason), ''), 'Club Promo Wallet Send'),
     jsonb_build_object(
       'op_id', v_op_id,
       'destination', v_dest,
       'source', 'club_promo_wallet',
       'actor_role', v_actor_role,
       'recipient_role', v_to_role,
       'pot_before', v_pot_before,
       'pot_after', v_pot_after,
       'recipient_balance_after', v_to_after),
     v_pot_after)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'destination', v_dest,
    'pot_before', v_pot_before,
    'pot_after', v_pot_after,
    'recipient_balance_after', v_to_after);
end
$function$

public.fn_promo_wallet_send_core_2026100.def:
CREATE OR REPLACE FUNCTION public.fn_promo_wallet_send_core_20261004(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor          uuid := auth.uid();
  v_actor_role     text;
  v_dest           text := lower(coalesce(p_destination, 'player_wallet'));
  v_op_id          uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior          record;
  v_sender_id      uuid;
  v_sender_promo   numeric;
  v_sender_after   numeric;
  v_to_role        text;
  v_to_agent_id    uuid;
  v_to_after       numeric;
  v_tx_id          uuid;
begin
  IF p_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
  END IF;
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null
     or v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only An Agent Or Club Staff May Send From A Promo Wallet');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'promo_wallet_send'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'sender_promo_after', (v_prior.metadata ->> 'sender_promo_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false,
      'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  end if;
  if v_dest not in ('player_wallet', 'agent_wallet', 'cashier_agent_wallet', 'cashier_promo_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Destination Wallet');
  end if;
  if p_to_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recipient');
  end if;
  if p_to_user_id = v_actor then
    return jsonb_build_object('success', false, 'error', 'A Promo Wallet Cannot Send To Itself');
  end if;

  if not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_to_user_id) then
    return jsonb_build_object('success', false,
      'error', 'That Member Is Not In Your Downline');
  end if;

  select a.id, coalesce(a.promo_wallet_balance, 0)
    into v_sender_id, v_sender_promo
    from agents a
   where a.club_id = p_club_id and a.user_id = v_actor
   for update;
  if v_sender_id is null then
    return jsonb_build_object('success', false,
      'error', 'You Do Not Hold A Promo Wallet In This Club');
  end if;
  if v_sender_promo < p_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient Promo Wallet Balance',
      'balance', v_sender_promo, 'requested', p_amount);
  end if;

  select cm.role into v_to_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_to_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_to_role is null then
    return jsonb_build_object('success', false, 'error', 'Recipient Is Not An Active Member Of This Club');
  end if;
  if v_dest in ('agent_wallet', 'cashier_agent_wallet', 'cashier_promo_wallet')
     and v_to_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only Staff Or Agents Hold A Promo Wallet');
  end if;

  if v_dest = 'player_wallet' and v_to_role = 'admin' then
    return jsonb_build_object('success', false, 'error', 'An Admin Does Not Hold A Player Wallet');
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE `promo_send` row from the sender's
  -- promo float to the wallet that receives it, keyed and correlated on the
  -- op. The agents trigger is skipped for both promo writes: a player
  -- recipient's club_members trigger writes the row with the promo float as
  -- counterparty; an agent recipient (both sides in `agents`) gets the row
  -- posted explicitly below. Never a refusal.
  perform public.fn_ca_declare_ledger('promo_send', 'promo_wallet', v_actor, null,
    'promo_send:' || v_op_id::text, array['agents']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  update agents
     set promo_wallet_balance = coalesce(promo_wallet_balance, 0) - p_amount,
         updated_at = now()
   where id = v_sender_id
   returning promo_wallet_balance into v_sender_after;

  if v_dest = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;
  else
    v_to_agent_id := public.fn_ensure_agent_row(p_club_id, p_to_user_id, v_to_role);
    if v_to_agent_id is null then
      raise exception 'could not ensure agents row for % in club %', p_to_user_id, p_club_id;
    end if;
    if v_dest = 'cashier_agent_wallet' then
      update agents set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + p_amount, updated_at = now()
       where id = v_to_agent_id returning agent_wallet_balance into v_to_after;
    else
      update agents set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount, updated_at = now()
       where id = v_to_agent_id returning promo_wallet_balance into v_to_after;
    end if;
    perform set_config('app.ledger_idempotency_key', '', true);
    perform public.fn_ca_post_leg('promo_send', 'promo_wallet', v_actor, case when v_dest = 'cashier_agent_wallet' then 'agent_wallet' else 'promo_wallet' end, p_to_user_id,
      p_amount, p_club_id, 'promo_send:' || v_op_id::text,
      'Promo wallet send to a downline agent promo wallet (fn_promo_wallet_send)');
  end if;

  perform set_config('app.ledger_autoskip_agents', '', true);

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, v_actor, p_to_user_id, p_amount, 'promo_wallet_send',
     coalesce(nullif(btrim(p_reason), ''), 'Promo Wallet Send'),
     jsonb_build_object(
       'op_id', v_op_id,
       'destination', v_dest,
       'source', 'promo_wallet',
       'actor_role', v_actor_role,
       'recipient_role', v_to_role,
       'sender_promo_after', v_sender_after,
       'recipient_balance_after', v_to_after),
     null)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'destination', v_dest,
    'sender_promo_after', v_sender_after,
    'recipient_balance_after', v_to_after);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where club_id = p_club_id
       and transaction_type = 'promo_wallet_send'
       and from_user_id = v_actor
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    if v_prior.id is null then
      raise;
    end if;
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'sender_promo_after', (v_prior.metadata ->> 'sender_promo_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
end
$function$

public.fn_union_send_to_member_zd3core(p.def:
CREATE OR REPLACE FUNCTION public.fn_union_send_to_member_zd3core(p_union_id uuid, p_target_user_id uuid, p_kind text, p_amount numeric, p_source_wallet text, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor      uuid := auth.uid();
  v_source     text;
  v_after      numeric;
  v_dia_after  numeric;
  v_club       uuid;
  v_role       text;
  v_is_club    boolean;
  v_agent_row  uuid;
  v_to_after   numeric;
  v_dest       text;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    if not public.fn_union_can_manage_wallets(p_union_id, v_actor) then
      return jsonb_build_object('success', false, 'error', 'Only the union owner, co-owner or an admin can send from union wallets.');
    end if;
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'amount must be > 0');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false, 'error', 'chips move in hundredths at most');
  end if;
  -- 2026-09-07 (Diamond Accounting Standard DR2, ruling): a union send of diamonds credited a player with
  -- no debit anywhere - a mint of up to 100,000 per call outside the Mint. Diamonds are issued only by
  -- fn_ca_mint. The diamonds branch below is unreachable and kept only as history.
  if p_kind not in ('chips','promo') then
    return jsonb_build_object('success', false, 'error', 'kind must be chips or promo. Diamonds are issued only by the Mint (Diamond Accounting Standard DR2).');
  end if;

  /* ZERO-DRIFT round 2 (2026-08-31): duplicate-send suppression. An identical
     union send (union, recipient, kind, amount, actor) inside 20 seconds is a
     retry, not a second intent.
     2026-10-09 (cashier launch audit C6-02): it now matches all five. It
     matched the union, the amount and the actor only, so a send of the same
     amount to a DIFFERENT member, or of the other kind, inside 20 seconds was
     answered success with nothing moved. The union-side row names no
     recipient; the recipient-side ledger leg this send journals in the same
     transaction (union_wallet -> the member's wallet, same instant) does. */
  if p_kind in ('chips','promo') and exists (
      select 1 from union_wallet_transactions t
       where t.union_id = p_union_id
         and t.direction = 'debit'
         and t.amount = p_amount
         and t.tx_type = case when p_kind = 'promo' then 'promo_member_send' else 'member_send' end
         and t.created_by is not distinct from v_actor
         and t.created_at > now() - interval '20 seconds'
         and exists (
           select 1 from chip_ledger l
            where l.to_entity_id = p_target_user_id
              and l.created_at = t.created_at
              and l.from_type = 'union_wallet'
              and l.from_entity_id = p_union_id
              and l.category = case when p_kind = 'promo' then 'promo_send' else 'union_send' end
              and l.amount = p_amount)) then
    return jsonb_build_object('success', true, 'duplicate_suppressed', true,
      'note', 'an identical send was recorded seconds ago; nothing moved twice');
  end if;

  select cm.club_id into v_club
    from club_members cm
   where cm.user_id = p_target_user_id
     and coalesce(cm.status, 'active') in ('active','approved')
     and cm.club_id = public.fn_player_home_club(p_target_user_id, null)
     and cm.club_id in (select uc.club_id from union_clubs uc where uc.union_id = p_union_id)
   limit 1;
  if v_club is null then
    select cm.club_id into v_club
      from club_members cm
     where cm.user_id = p_target_user_id
       and coalesce(cm.status, 'active') in ('active','approved')
       and cm.club_id in (select uc.club_id from union_clubs uc where uc.union_id = p_union_id)
     order by coalesce(cm.chip_balance, 0) desc, cm.club_id
     limit 1;
  end if;
  if v_club is null then
    select cm.club_id into v_club
      from club_members cm
     where cm.user_id = p_target_user_id
       and coalesce(cm.status, 'active') in ('active','approved')
       and cm.club_id = p_union_id
     limit 1;
  end if;
  if v_club is null then
    return jsonb_build_object('success', false, 'error', 'That player is not a member of this union.');
  end if;
  v_is_club := exists (select 1 from clubs c where c.id = v_club);
  select cm.role into v_role from club_members cm
   where cm.club_id = v_club and cm.user_id = p_target_user_id
     and coalesce(cm.status, 'active') in ('active','approved')
   limit 1;

  if p_kind = 'diamonds' then
    if p_amount <> floor(p_amount) then
      return jsonb_build_object('success', false, 'error', 'diamonds must be a whole number');
    end if;
    if p_amount > 100000 then
      return jsonb_build_object('success', false, 'error', 'maximum 100,000 diamonds per send');
    end if;
    /* DR2, LOG-ONLY (2026-09-03). This credit has no debit: no union diamond wallet is
       decremented, nothing is drawn from the Mint, and no budget is consumed. It creates
       diamonds out of nothing, up to 100,000 per call. It is RECORDED and allowed to
       proceed; refusing a live grant is Dan's call (decision 6.6, fund it or remove it). */
    perform public.fn_ca_diamond_incident(
      'DR2:union_diamond_grant_unfunded', 'warning', p_target_user_id, p_amount,
      'fn_union_send_to_member_zd3core',
      jsonb_build_object('union_id', p_union_id,
                         'source_wallet', p_source_wallet,
                         'club_id', v_club,
                         'actor', v_actor,
                         'note', 'diamonds credited with no debit on any wallet and no mint row; unfunded issuance'));
    update profiles set diamonds = coalesce(diamonds, 0) + p_amount
     where id = p_target_user_id
    returning diamonds into v_dia_after;
    if v_dia_after is null then
      return jsonb_build_object('success', false, 'error', 'player profile not found');
    end if;
    insert into diamond_transactions (user_id, type, amount, balance_after, description, transaction_type, source, metadata, counterparty, issuance_class)
    values (p_target_user_id, 'credit', p_amount, v_dia_after,
            coalesce(p_note, 'Union grant'), 'union_grant', 'union',
            jsonb_build_object('union_id', p_union_id, 'granted_by', v_actor),
            'union:' || p_union_id::text, 'promotional');
    return jsonb_build_object('success', true, 'kind', 'diamonds', 'balance_after', v_dia_after);
  end if;

  /* ZERO-DRIFT round 2: the recipient-side credit journals ONE clean ledger
     row (union_wallet -> player/agent wallet); the union-side debit is
     autoskipped because union_wallet_transactions already records it and a
     second ledger row would double-post the flow. */
  perform set_config('app.ledger_category',
                     case when p_kind = 'promo' then 'promo_send' else 'union_send' end, true);
  perform set_config('app.ledger_counterparty', 'union_wallet', true);
  perform set_config('app.ledger_counterparty_entity', p_union_id::text, true);
  perform set_config('app.ledger_autoskip_union_wallets', '1', true);
  perform set_config('app.ledger_counterparty_label',
                     case when p_kind = 'promo' then 'union_wallets.promo_wallet' else '' end, true);

  if p_kind = 'promo' then
    update union_wallets
       set promo_wallet = promo_wallet - p_amount, updated_at = now()
     where union_id = p_union_id and coalesce(promo_wallet, 0) >= p_amount
    returning promo_wallet into v_after;
    if v_after is null then
      return jsonb_build_object('success', false, 'error', 'Insufficient promo wallet balance.');
    end if;

    if v_is_club and v_role in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
      v_dest := 'promo_float';
      v_agent_row := public.fn_ensure_agent_row(v_club, p_target_user_id, v_role);
      if v_agent_row is null then
        raise exception 'could not ensure agents row for % in club %', p_target_user_id, v_club;
      end if;
      update agents
         set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount,
             updated_at = now()
       where id = v_agent_row
       returning promo_wallet_balance into v_to_after;
    else
      v_dest := 'player_wallet';
      update club_members
         set chip_balance = coalesce(chip_balance, 0) + p_amount,
             updated_at = now()
       where club_id = v_club and user_id = p_target_user_id
       returning chip_balance into v_to_after;
    end if;
    if v_to_after is null then
      raise exception 'union promo credit landed nowhere for % in %', p_target_user_id, v_club;
    end if;

    insert into union_wallet_transactions
      (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes, created_by)
    values
      (p_union_id, case when v_is_club then v_club else null end,
       'promo_wallet', 'debit', p_amount, v_after, 'promo_member_send',
       coalesce(p_note, 'Union promo to member'), v_actor);
    if v_is_club then
      insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after,
                                     metadata)
      values (v_club, v_actor, p_target_user_id, p_amount, 'union_promo_send',
              coalesce(p_note, 'Union promo to member'), v_to_after,
              jsonb_build_object('union_id', p_union_id, 'destination', v_dest));
    end if;
    return jsonb_build_object('success', true, 'kind', 'promo', 'wallet_after', v_after,
                              'destination', v_dest, 'recipient_balance_after', v_to_after);
  end if;

  v_source := coalesce(p_source_wallet, 'chips');
  if v_source not in ('chips','rake','promo') then
    return jsonb_build_object('success', false, 'error', 'source wallet must be chips, rake or promo');
  end if;

  perform set_config('app.ledger_counterparty_label',
                     case v_source when 'chips' then 'union_wallets.chip_balance'
                                   when 'rake' then 'union_wallets.rake_wallet'
                                   else 'union_wallets.promo_wallet' end, true);
  if v_source = 'chips' then
    update union_wallets set chip_balance = chip_balance - p_amount, updated_at = now()
     where union_id = p_union_id and coalesce(chip_balance, 0) >= p_amount
    returning chip_balance into v_after;
  elsif v_source = 'rake' then
    update union_wallets set rake_wallet = rake_wallet - p_amount, updated_at = now()
     where union_id = p_union_id and coalesce(rake_wallet, 0) >= p_amount
    returning rake_wallet into v_after;
  else
    update union_wallets set promo_wallet = promo_wallet - p_amount, updated_at = now()
     where union_id = p_union_id and coalesce(promo_wallet, 0) >= p_amount
    returning promo_wallet into v_after;
  end if;

  if v_after is null then
    return jsonb_build_object('success', false, 'error', 'Insufficient balance in the selected union wallet.');
  end if;

  if v_is_club and v_role in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
    v_dest := 'agent_wallet';
    v_agent_row := public.fn_ensure_agent_row(v_club, p_target_user_id, v_role);
    if v_agent_row is null then
      raise exception 'could not ensure agents row for % in club %', p_target_user_id, v_club;
    end if;
    update agents
       set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + p_amount,
           updated_at = now()
     where id = v_agent_row
     returning agent_wallet_balance into v_to_after;
  else
    v_dest := 'player_wallet';
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = v_club and user_id = p_target_user_id
     returning chip_balance into v_to_after;
  end if;
  if v_to_after is null then
    raise exception 'union chip credit landed nowhere for % in %', p_target_user_id, v_club;
  end if;

  insert into union_wallet_transactions
    (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes, created_by)
  values
    (p_union_id, case when v_is_club then v_club else null end,
     case v_source when 'chips' then 'chip_balance' when 'rake' then 'rake_wallet' else 'promo_wallet' end,
     'debit', p_amount, v_after, 'member_send',
     coalesce(p_note, 'Union chips to member (' || v_source || ' wallet)'), v_actor);
  if v_is_club then
    insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after,
                                   metadata)
    values (v_club, v_actor, p_target_user_id, p_amount, 'union_member_send',
            coalesce(p_note, 'Union chips to member (' || v_source || ' wallet)'), v_to_after,
            jsonb_build_object('union_id', p_union_id, 'source_wallet', v_source, 'destination', v_dest));
  end if;

  return jsonb_build_object('success', true, 'kind', 'chips', 'source', v_source,
                            'wallet_after', v_after,
                            'destination', v_dest, 'recipient_balance_after', v_to_after);
end $function$

public.fn_cashier_cashout_transition(p_a.def:
CREATE OR REPLACE FUNCTION public.fn_cashier_cashout_transition(p_action text, p_club_id uuid, p_cashout_id uuid, p_amount numeric, p_expected_actor_id uuid, p_op_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid();actual_role text;kind text;request_status text;v_release_type text;
 note text:=NULLIF(btrim(p_note),'');fingerprint jsonb;prior public.accounting_cashier_events%ROWTYPE;
 r public.cashout_requests%ROWTYPE;s public.chip_escrow%ROWTYPE;h public.accounting_cashier_events%ROWTYPE;
 e public.accounting_cashier_events%ROWTYPE;member public.club_members%ROWTYPE;agent public.agents%ROWTYPE;
 club public.clubs%ROWTYPE;wallet_before numeric;wallet_after numeric;agent_row_id uuid;assigned uuid;
 request_id uuid:=p_cashout_id;escrow_id uuid;event_id uuid:=gen_random_uuid();invoice_id uuid:=gen_random_uuid();tx_id uuid:=gen_random_uuid();leg_id uuid;
 at_time timestamptz:=transaction_timestamp();issue_time timestamptz;leg_count int;rows_written int;persisted numeric;
 tx_type text;tx_note text;tx_from uuid;tx_to uuid;audience uuid[];payload jsonb;result jsonb;wallet_user uuid;
 old_category text:=current_setting('app.ledger_category',true);old_cp text:=current_setting('app.ledger_counterparty',true);
 old_entity text:=current_setting('app.ledger_counterparty_entity',true);old_key text:=current_setting('app.ledger_idempotency_key',true);
 old_settlement text:=current_setting('app.ledger_settlement',true);old_tournament text:=current_setting('app.ledger_tournament',true);
 old_hand text:=current_setting('app.ledger_hand_id',true);old_tournament_id text:=current_setting('app.ledger_tournament_id',true);
BEGIN
  -- Serialize the existing agreement before any operation/hierarchy/row lock.
  -- Nested callers reacquire the same transaction lock; no new money path.
  IF p_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
  END IF;

 IF p_action IS NULL OR p_action NOT IN('hold','approval','release','expiry_refund') OR p_club_id IS NULL OR p_op_id IS NULL
  OR (p_action='hold' AND p_cashout_id IS NOT NULL) OR (p_action<>'hold' AND p_cashout_id IS NULL)
 THEN RAISE EXCEPTION 'cashier_intent_incomplete' USING ERRCODE='22023';END IF;
 IF p_action='expiry_refund' THEN
  IF actor IS NOT NULL OR p_expected_actor_id IS NOT NULL
  THEN RAISE EXCEPTION 'cashier_system_actor_required' USING ERRCODE='42501';END IF;
 ELSE
  IF actor IS NULL OR actor IS DISTINCT FROM p_expected_actor_id
  THEN RAISE EXCEPTION 'cashier_account_changed' USING ERRCODE='42501';END IF;
 END IF;
 IF p_amount IS NULL OR p_amount::text IN('NaN','Infinity','-Infinity') OR p_amount<=0
    OR p_amount>1000000000 OR p_amount<>round(p_amount,2)
 THEN RAISE EXCEPTION 'cashier_invalid_amount' USING ERRCODE='22023';END IF;
 fingerprint:=jsonb_build_object('action',p_action,'actor',actor,'club_id',p_club_id,'cashout_id',p_cashout_id,
   'amount',round(p_amount,2)::text,'note',note);
 PERFORM pg_advisory_xact_lock(hashtextextended('cashout-op:'||COALESCE(actor::text,'system')||':'||p_op_id::text,0));
 -- Hierarchy first: never take a request or wallet row before this scope lock.
 PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));
 SELECT * INTO club FROM public.clubs WHERE id=p_club_id FOR UPDATE;
 IF NOT FOUND OR club.owner_id IS NULL THEN RAISE EXCEPTION 'cashier_club_unavailable' USING ERRCODE='23514';END IF;
 SELECT * INTO prior FROM public.accounting_cashier_events WHERE actor_user_id IS NOT DISTINCT FROM actor AND op_id=p_op_id;
 IF FOUND THEN
  IF prior.operation_fingerprint IS DISTINCT FROM fingerprint
  THEN RAISE EXCEPTION 'cashier_operation_conflict' USING ERRCODE='22023';END IF;
  RETURN public.fn_cashier_operation_receipt(prior.id,true);
 END IF;
 -- Legacy chips alone cannot certify a canonical hold, delivery or replay.
 IF EXISTS(SELECT 1 FROM public.chip_transactions t WHERE t.metadata->>'op_id'=p_op_id::text
   AND t.transaction_type IN('cashout_request_escrow','cashout_approved','cashout_cancelled','cashout_denied','cashout_expired_refund')
   AND (t.from_user_id=actor OR t.to_user_id=actor OR (actor IS NULL AND t.transaction_type='cashout_expired_refund')))
 THEN RAISE EXCEPTION 'cashier_legacy_operation_unverified' USING ERRCODE='23514';END IF;
 IF current_setting('app.ledger_autoskip_club_members',true)='1' OR current_setting('app.ledger_autoskip_agents',true)='1'
 THEN RAISE EXCEPTION 'cashier_journal_is_suppressed' USING ERRCODE='23514';END IF;
 IF p_action='hold' THEN
  SELECT agent_id INTO assigned FROM public.club_members WHERE club_id=p_club_id AND user_id=actor;
  PERFORM public.fn_cashier_lock_authority(p_club_id,actor,actor,COALESCE(assigned,club.owner_id));
  SELECT * INTO member FROM public.club_members WHERE club_id=p_club_id AND user_id=actor FOR UPDATE;
  IF NOT FOUND OR COALESCE(member.status,'active') NOT IN('active','approved')
    OR member.role NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent','player','member')
  THEN RAISE EXCEPTION 'cashier_player_wallet_unavailable' USING ERRCODE='42501';END IF;
  actual_role:=member.role;assigned:=COALESCE(member.agent_id,club.owner_id);
  IF assigned IS NULL OR assigned=actor OR public.fn_club_cashier_can_transact(p_club_id,assigned,actor) IS NOT TRUE
    OR COALESCE(public.fn_club_bank_role(p_club_id,assigned),'') NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent')
  THEN RAISE EXCEPTION 'cashier_assigned_cashier_unavailable' USING ERRCODE='42501';END IF;
  IF EXISTS(SELECT 1 FROM public.cashout_requests WHERE club_id=p_club_id AND player_id=actor AND status='pending')
  THEN RAISE EXCEPTION 'cashier_pending_request_exists' USING ERRCODE='23514';END IF;
  request_id:=gen_random_uuid();escrow_id:=gen_random_uuid();kind:='hold';request_status:='pending';wallet_user:=actor;
  wallet_before:=member.chip_balance;
 ELSE
  SELECT * INTO r FROM public.cashout_requests WHERE id=p_cashout_id FOR UPDATE;
  IF NOT FOUND OR r.club_id IS DISTINCT FROM p_club_id OR r.amount IS DISTINCT FROM p_amount
  THEN RAISE EXCEPTION 'cashier_request_intent_mismatch' USING ERRCODE='22023';END IF;
  IF r.status IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'cashier_request_already_terminal' USING ERRCODE='23514';END IF;
  SELECT * INTO s FROM public.chip_escrow WHERE cashout_request_id=r.id FOR UPDATE;
  IF NOT FOUND OR s.club_id IS DISTINCT FROM r.club_id OR s.player_id IS DISTINCT FROM r.player_id
    OR s.amount IS DISTINCT FROM r.amount OR s.table_id IS NOT NULL OR s.released_at IS NOT NULL OR s.release_type IS NOT NULL
    OR s.locked_at IS DISTINCT FROM r.created_at
  THEN RAISE EXCEPTION 'cashier_escrow_unverified' USING ERRCODE='23514';END IF;
  SELECT * INTO h FROM public.accounting_cashier_events WHERE cashout_id=r.id AND event_slot='hold';
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_legacy_hold_unverified' USING ERRCODE='23514';END IF;
  PERFORM public.fn_cashier_operation_receipt(h.id,true);
  escrow_id:=s.id;assigned:=r.agent_id;
  PERFORM public.fn_cashier_lock_authority(p_club_id,actor,r.player_id,assigned);
  IF p_action='expiry_refund' THEN kind:='expiry_refund';actual_role:='system';
  ELSIF p_action='release' AND actor=r.player_id THEN kind:='cancellation';
  ELSE
   actual_role:=public.fn_club_bank_role(p_club_id,actor);
   IF actor=r.player_id OR COALESCE(actual_role,'') NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent')
      OR public.fn_club_cashier_can_transact(p_club_id,actor,r.player_id) IS NOT TRUE
   THEN RAISE EXCEPTION 'cashier_current_authority_required' USING ERRCODE='42501';END IF;
   kind:=CASE p_action WHEN 'approval' THEN 'approval' ELSE 'decline' END;
  END IF;
  request_status:=CASE kind WHEN 'approval' THEN 'approved' WHEN 'cancellation' THEN 'cancelled' WHEN 'decline' THEN 'rejected' ELSE 'expired' END;
  v_release_type:=CASE kind WHEN 'approval' THEN 'completed' ELSE request_status END;
  IF kind='approval' THEN
   agent_row_id:=public.fn_ensure_agent_row(p_club_id,actor,actual_role);
   SELECT * INTO agent FROM public.agents WHERE id=agent_row_id AND club_id=p_club_id AND user_id=actor FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'cashier_destination_wallet_unavailable' USING ERRCODE='23503';END IF;
   wallet_before:=agent.agent_wallet_balance;wallet_user:=actor;
  ELSE
   SELECT * INTO member FROM public.club_members WHERE club_id=p_club_id AND user_id=r.player_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'cashier_refund_wallet_missing' USING ERRCODE='23503';END IF;
   IF kind='cancellation' THEN
    actual_role:=member.role;
    IF actual_role IS NULL OR actual_role NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent','player','member')
    THEN RAISE EXCEPTION 'cashier_player_role_unavailable' USING ERRCODE='42501';END IF;
   END IF;
   wallet_before:=member.chip_balance;wallet_user:=r.player_id;
  END IF;
 END IF;
 IF wallet_before IS NULL OR wallet_before<0 OR wallet_before::text IN('NaN','Infinity','-Infinity') OR wallet_before<>round(wallet_before,2)
   OR (kind='hold' AND wallet_before<p_amount)
 THEN RAISE EXCEPTION 'cashier_wallet_balance_unverified' USING ERRCODE='23514';END IF;
 wallet_after:=wallet_before+CASE WHEN kind='hold' THEN -p_amount ELSE p_amount END;
 -- Ambient unrelated ledger context must never contaminate this custody leg.
 PERFORM set_config('app.ledger_settlement','',true);PERFORM set_config('app.ledger_tournament','',true);
 PERFORM set_config('app.ledger_hand_id','',true);PERFORM set_config('app.ledger_tournament_id','',true);
 PERFORM public.fn_ca_declare_ledger(CASE WHEN kind='hold' THEN 'escrow_hold' ELSE 'escrow_release' END,
  'escrow',escrow_id,NULL,'cashout:'||request_id::text||CASE WHEN kind='hold' THEN ':hold' ELSE ':release' END,NULL);
 IF kind='approval' THEN
  UPDATE public.agents SET agent_wallet_balance=wallet_after,updated_at=at_time WHERE id=agent.id RETURNING agent_wallet_balance INTO persisted;
 ELSE
  UPDATE public.club_members SET chip_balance=wallet_after,updated_at=at_time WHERE club_id=member.club_id AND user_id=member.user_id RETURNING chip_balance INTO persisted;
 END IF;
 GET DIAGNOSTICS rows_written=ROW_COUNT;
 IF rows_written<>1 OR persisted IS DISTINCT FROM wallet_after THEN RAISE EXCEPTION 'cashier_wallet_write_missing' USING ERRCODE='23514';END IF;
 PERFORM set_config('app.ledger_category',COALESCE(old_category,''),true);PERFORM set_config('app.ledger_counterparty',COALESCE(old_cp,''),true);
 PERFORM set_config('app.ledger_counterparty_entity',COALESCE(old_entity,''),true);PERFORM set_config('app.ledger_idempotency_key',COALESCE(old_key,''),true);
 PERFORM set_config('app.ledger_settlement',COALESCE(old_settlement,''),true);PERFORM set_config('app.ledger_tournament',COALESCE(old_tournament,''),true);
 PERFORM set_config('app.ledger_hand_id',COALESCE(old_hand,''),true);PERFORM set_config('app.ledger_tournament_id',COALESCE(old_tournament_id,''),true);
 IF kind='hold' THEN
  INSERT INTO public.cashout_requests(id,club_id,player_id,agent_id,amount,status,player_note,created_at,updated_at)
   VALUES(request_id,p_club_id,actor,assigned,p_amount,'pending',note,at_time,at_time) RETURNING * INTO r;
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_request_write_missing' USING ERRCODE='23514';END IF;
  INSERT INTO public.chip_escrow(id,cashout_request_id,club_id,player_id,amount,locked_at)
   VALUES(escrow_id,request_id,p_club_id,actor,p_amount,at_time) RETURNING * INTO s;
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_escrow_write_missing' USING ERRCODE='23514';END IF;
 ELSE
  UPDATE public.chip_escrow SET released_at=at_time,release_type=v_release_type WHERE id=escrow_id RETURNING * INTO s;
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_escrow_write_missing' USING ERRCODE='23514';END IF;
  UPDATE public.cashout_requests SET status=request_status,
   agent_note=CASE WHEN kind IN('approval','decline') THEN note ELSE agent_note END,
   acknowledged_at=CASE WHEN kind IN('approval','decline') THEN at_time ELSE NULL END,
   completed_at=CASE WHEN kind='approval' THEN at_time ELSE NULL END,
   cancelled_at=CASE WHEN kind IN('cancellation','decline','expiry_refund') THEN at_time ELSE NULL END,updated_at=at_time
   WHERE id=request_id RETURNING * INTO r;
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_request_write_missing' USING ERRCODE='23514';END IF;
 END IF;
 SELECT count(*),(array_agg(id))[1] INTO leg_count,leg_id FROM public.chip_ledger
  WHERE idempotency_key='cashout:'||request_id::text||CASE WHEN kind='hold' THEN ':hold' ELSE ':release' END;
 IF leg_count<>1 THEN RAISE EXCEPTION 'cashier_physical_ledger_missing_or_duplicate' USING ERRCODE='23514';END IF;
 tx_type:=CASE kind WHEN 'hold' THEN 'cashout_request_escrow' WHEN 'approval' THEN 'cashout_approved'
   WHEN 'cancellation' THEN 'cashout_cancelled' WHEN 'decline' THEN 'cashout_denied' ELSE 'cashout_expired_refund' END;
 tx_note:=COALESCE(note,CASE kind WHEN 'hold' THEN 'Cash Out Requested. Chips Held In Escrow'
  WHEN 'approval' THEN 'Cash Out Approved. Escrow Released Into The Agent Wallet'
  WHEN 'cancellation' THEN 'Cash Out Cancelled. Escrow Returned To Player'
  WHEN 'decline' THEN 'Cash Out Declined. Escrow Returned To Player' ELSE 'Stale Cash Out Expired. Escrow Returned To Player' END);
 tx_from:=CASE WHEN kind IN('hold','approval') THEN r.player_id ELSE actor END;
 tx_to:=CASE kind WHEN 'hold' THEN assigned WHEN 'approval' THEN actor ELSE r.player_id END;
 INSERT INTO public.chip_transactions(id,club_id,from_user_id,to_user_id,amount,transaction_type,notes,related_cashout_id,metadata,balance_after,created_at)
  VALUES(tx_id,p_club_id,tx_from,tx_to,p_amount,tx_type,tx_note,request_id,
   jsonb_build_object('op_id',p_op_id,'cashier_document_version',1,'event_id',event_id,'assigned_agent_id',assigned,
     'actor_user_id',actor,'actor_role',actual_role),wallet_after,at_time);
 GET DIAGNOSTICS rows_written=ROW_COUNT;
 IF rows_written<>1 THEN RAISE EXCEPTION 'cashier_transaction_write_missing' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO audience FROM unnest(CASE WHEN kind='hold' THEN ARRAY[r.player_id] ELSE ARRAY[club.owner_id,r.player_id] END||ARRAY[
   CASE WHEN kind IN('approval','decline') THEN actor ELSE assigned END]
   ||CASE WHEN kind IN('approval','decline') AND assigned IS NOT NULL
        AND EXISTS(SELECT 1 FROM public.profiles ap WHERE ap.id=assigned)
      THEN ARRAY[assigned] ELSE ARRAY[]::uuid[] END) x;
 IF cardinality(audience)<2 OR EXISTS(SELECT 1 FROM unnest(audience) x WHERE x IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=x))
 THEN RAISE EXCEPTION 'cashier_document_audience_unavailable' USING ERRCODE='23514';END IF;
 issue_time:=clock_timestamp();
 INSERT INTO public.accounting_cashier_events(id,contract_version,cashout_id,escrow_id,source_transaction_id,source_ledger_id,invoice_id,event_slot,event_kind,
  hold_event_id,hold_invoice_id,club_id,player_id,assigned_agent_id,actor_user_id,actor_role,ledger_actor_user_id,
  issuer_representative_id,issuer_name,player_name,audience_user_ids,op_id,operation_fingerprint,accepted_note,transaction_note,amount,
  ledger_from_type,ledger_from_entity_id,ledger_to_type,ledger_to_entity_id,wallet_owner_id,wallet_before,wallet_after,occurred_at,issued_at)
 VALUES(event_id,1,request_id,escrow_id,tx_id,leg_id,invoice_id,CASE WHEN kind='hold' THEN 'hold' ELSE 'terminal' END,kind,
  h.id,h.invoice_id,p_club_id,r.player_id,assigned,actor,actual_role,COALESCE(actor,'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
  club.owner_id,COALESCE(NULLIF(btrim(club.name),''),'Club'),public.fn_notify_display_name(r.player_id),audience,p_op_id,fingerprint,note,tx_note,p_amount,
  CASE WHEN kind='hold' THEN 'player_wallet' ELSE 'escrow' END,CASE WHEN kind='hold' THEN r.player_id ELSE escrow_id END,
  CASE kind WHEN 'hold' THEN 'escrow' WHEN 'approval' THEN 'agent_wallet' ELSE 'player_wallet' END,
  CASE kind WHEN 'hold' THEN escrow_id WHEN 'approval' THEN actor ELSE r.player_id END,wallet_user,wallet_before,wallet_after,at_time,issue_time)
 RETURNING * INTO e;
 IF NOT FOUND THEN RAISE EXCEPTION 'cashier_event_write_missing' USING ERRCODE='23514';END IF;
 payload:=public.fn_cashier_event_payload(e);
 INSERT INTO public.settlement_invoices(id,club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
  gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,source_ledger_id,notes,created_at,updated_at)
 VALUES(invoice_id,p_club_id,'cashier_cashout','club',p_club_id::text,'player',r.player_id::text,p_amount,p_amount,0,
  jsonb_build_object('kind','cashier_cashout','cashier',payload),CASE WHEN kind='hold' THEN 'generated' ELSE 'paid' END,kind<>'hold',
  CASE WHEN kind='hold' THEN NULL ELSE at_time END,leg_id,'Recorded cashier chip custody event.',issue_time,issue_time);
 GET DIAGNOSTICS rows_written=ROW_COUNT;
 IF rows_written<>1 THEN RAISE EXCEPTION 'cashier_invoice_write_missing' USING ERRCODE='23514';END IF;
 -- Read stored rows after all triggers; RETURNING alone cannot establish survival.
 IF kind='approval' THEN SELECT agent_wallet_balance INTO persisted FROM public.agents WHERE id=agent.id AND club_id=p_club_id AND user_id=actor;
 ELSE SELECT chip_balance INTO persisted FROM public.club_members WHERE club_id=member.club_id AND user_id=member.user_id AND club_id=p_club_id AND user_id=wallet_user;END IF;
 IF NOT FOUND OR persisted IS DISTINCT FROM wallet_after THEN RAISE EXCEPTION 'cashier_wallet_write_changed' USING ERRCODE='23514';END IF;
 result:=public.fn_cashier_operation_receipt(event_id,false);
 RETURN result;
END $function$

public.fn_cashier_operation_receipt(p_ev.def:
CREATE OR REPLACE FUNCTION public.fn_cashier_operation_receipt(p_event_id uuid, p_replayed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO,YMD'
AS $function$
DECLARE e public.accounting_cashier_events%ROWTYPE; terminal public.accounting_cashier_events%ROWTYPE;
 r public.cashout_requests%ROWTYPE;s public.chip_escrow%ROWTYPE;payload jsonb;expected_status text;expected_release text;
BEGIN
 SELECT * INTO STRICT e FROM public.accounting_cashier_events WHERE id=p_event_id;
 SELECT * INTO r FROM public.cashout_requests WHERE id=e.cashout_id FOR UPDATE;
 SELECT * INTO s FROM public.chip_escrow WHERE id=e.escrow_id FOR UPDATE;
 payload:=public.fn_cashier_assert_delivery(e.id);
 IF r.id IS NULL OR s.id IS NULL OR r.club_id IS DISTINCT FROM e.club_id OR r.player_id IS DISTINCT FROM e.player_id
   OR r.agent_id IS DISTINCT FROM e.assigned_agent_id OR r.amount IS DISTINCT FROM e.amount
   OR s.cashout_request_id IS DISTINCT FROM r.id OR s.player_id IS DISTINCT FROM e.player_id
   OR s.club_id IS DISTINCT FROM e.club_id OR s.amount IS DISTINCT FROM e.amount OR s.table_id IS NOT NULL
   OR r.created_at IS NULL OR r.updated_at IS NULL OR NOT isfinite(r.created_at) OR NOT isfinite(r.updated_at)
   OR s.locked_at IS DISTINCT FROM r.created_at
 THEN RAISE EXCEPTION 'cashier_request_receipt_mismatch' USING ERRCODE='23514';END IF;
 IF e.event_kind='hold' THEN
  IF r.created_at IS DISTINCT FROM e.occurred_at OR r.player_note IS DISTINCT FROM e.accepted_note
  THEN RAISE EXCEPTION 'cashier_hold_request_mismatch' USING ERRCODE='23514';END IF;
  IF r.status='pending' THEN
   IF s.released_at IS NOT NULL OR s.release_type IS NOT NULL OR r.acknowledged_at IS NOT NULL
      OR r.completed_at IS NOT NULL OR r.cancelled_at IS NOT NULL OR r.updated_at IS DISTINCT FROM e.occurred_at
      OR EXISTS(SELECT 1 FROM public.accounting_cashier_events x WHERE x.cashout_id=r.id AND x.event_slot='terminal')
   THEN RAISE EXCEPTION 'cashier_pending_request_mismatch' USING ERRCODE='23514';END IF;
  ELSE
   SELECT * INTO terminal FROM public.accounting_cashier_events WHERE cashout_id=r.id AND event_slot='terminal';
   IF NOT p_replayed OR terminal.id IS NULL OR terminal.hold_event_id IS DISTINCT FROM e.id
   THEN RAISE EXCEPTION 'cashier_terminal_receipt_missing' USING ERRCODE='23514';END IF;
   PERFORM public.fn_cashier_operation_receipt(terminal.id,true);
  END IF;
 ELSE
  expected_status:=CASE e.event_kind WHEN 'approval' THEN 'approved' WHEN 'cancellation' THEN 'cancelled'
    WHEN 'decline' THEN 'rejected' ELSE 'expired' END;
  expected_release:=CASE e.event_kind WHEN 'approval' THEN 'completed' ELSE expected_status END;
  IF r.status IS DISTINCT FROM expected_status OR s.release_type IS DISTINCT FROM expected_release
    OR s.released_at IS DISTINCT FROM e.occurred_at OR r.updated_at IS DISTINCT FROM e.occurred_at
    OR r.acknowledged_at IS DISTINCT FROM (CASE WHEN e.event_kind IN('approval','decline') THEN e.occurred_at ELSE NULL::timestamptz END)
    OR r.completed_at IS DISTINCT FROM (CASE WHEN e.event_kind='approval' THEN e.occurred_at ELSE NULL::timestamptz END)
    OR r.cancelled_at IS DISTINCT FROM (CASE WHEN e.event_kind IN('cancellation','decline','expiry_refund') THEN e.occurred_at ELSE NULL::timestamptz END)
    OR (e.event_kind IN('approval','decline') AND r.agent_note IS DISTINCT FROM e.accepted_note)
  THEN RAISE EXCEPTION 'cashier_terminal_request_mismatch' USING ERRCODE='23514';END IF;
  PERFORM public.fn_cashier_assert_delivery(e.hold_event_id);
 END IF;
 expected_status:=CASE e.event_kind WHEN 'hold' THEN 'pending' WHEN 'approval' THEN 'approved'
   WHEN 'cancellation' THEN 'cancelled' WHEN 'decline' THEN 'rejected' ELSE 'expired' END;
 RETURN payload||jsonb_build_object('success',true,'replayed',p_replayed,'op_id',e.op_id,
   'request_status',expected_status,'accepted_note',e.accepted_note,'actor_wallet_after',CASE WHEN e.event_kind IN('hold','approval','cancellation') THEN round(e.wallet_after,2)::text ELSE NULL END,
   'cashier',payload,'request',jsonb_build_object('id',r.id,'club_id',r.club_id,'player_id',r.player_id,'agent_id',r.agent_id,
    'amount',round(r.amount,2)::text,'status',r.status,'created_at',r.created_at,'updated_at',r.updated_at,
    'acknowledged_at',r.acknowledged_at,'completed_at',r.completed_at,'cancelled_at',r.cancelled_at,
    'player_note',r.player_note,'agent_note',r.agent_note));
END $function$

public.fn_cashier_lock_authority(p_club_.def:
CREATE OR REPLACE FUNCTION public.fn_cashier_lock_authority(p_club_id uuid, p_actor uuid, p_target uuid, p_assigned uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE before_ids uuid[];after_ids uuid[];
BEGIN
 WITH RECURSIVE chain AS (
  SELECT m.user_id,m.agent_id,0 depth FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id=ANY(ARRAY[p_actor,p_target,p_assigned])
  UNION ALL SELECT m.user_id,m.agent_id,c.depth+1 FROM chain c JOIN public.club_members m ON m.club_id=p_club_id AND m.user_id=c.agent_id WHERE c.depth<20
 ) SELECT array_agg(DISTINCT user_id ORDER BY user_id) INTO before_ids FROM chain;
 PERFORM m.user_id FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id=ANY(before_ids) ORDER BY m.user_id FOR UPDATE;
 WITH RECURSIVE chain AS (
  SELECT m.user_id,m.agent_id,0 depth FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id=ANY(ARRAY[p_actor,p_target,p_assigned])
  UNION ALL SELECT m.user_id,m.agent_id,c.depth+1 FROM chain c JOIN public.club_members m ON m.club_id=p_club_id AND m.user_id=c.agent_id WHERE c.depth<20
 ) SELECT array_agg(DISTINCT user_id ORDER BY user_id) INTO after_ids FROM chain;
 IF before_ids IS DISTINCT FROM after_ids THEN RAISE EXCEPTION 'cashier_authority_changed_during_lock' USING ERRCODE='55000';END IF;
END $function$

public.atomic_deduct_wallet_and_log(p_us.def:
CREATE OR REPLACE FUNCTION public.atomic_deduct_wallet_and_log(p_user_id uuid, p_amount numeric, p_category text DEFAULT 'debit'::text, p_description text DEFAULT ''::text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_related_entity_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_balance numeric;
  v_club_id uuid;
  v_context_club uuid;
  v_context_tournament uuid;
  v_declared_club uuid;
  v_declared_text text;
  v_has_club boolean;
BEGIN
  IF p_user_id IS NULL
     OR p_amount IS NULL
     OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount <= 0
     OR p_amount <> round(p_amount,2) THEN
    RAISE EXCEPTION 'wallet debit requires a positive two-decimal amount'
      USING ERRCODE='22023';
  END IF;

  v_declared_text:=NULLIF(current_setting('app.ledger_club_id',true),'');
  IF v_declared_text IS NOT NULL THEN
    BEGIN
      v_declared_club:=v_declared_text::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'wallet debit declared club is not a UUID'
        USING ERRCODE='22023';
    END;
    v_club_id:=v_declared_club;
  END IF;

  IF p_table_id IS NOT NULL THEN
    SELECT t.club_id, t.tournament_id INTO v_context_club, v_context_tournament
      FROM public.tables t
     WHERE t.id=p_table_id;
    IF v_context_club IS NULL THEN
      RAISE EXCEPTION 'wallet debit table % has no club context',p_table_id
        USING ERRCODE='P0002';
    END IF;
    IF v_context_tournament IS NOT NULL THEN
      -- THE ENTRY IS CHARGED TO THE WALLET THE ENTRY IS STAMPED WITH
      -- (2026-09-10): a tournament table resolves the wallet the way the
      -- entry stamp does, so a rebuy at a union event comes from the same
      -- member-club wallet the buy-in came from.
      v_context_club:=public.fn_tournament_club_for_user(
        p_user_id,v_context_tournament,v_club_id);
      IF v_context_club IS NULL THEN
        RAISE EXCEPTION 'no club wallet in the union of tournament % resolves for player %',
          v_context_tournament,p_user_id USING ERRCODE='42501';
      END IF;
    END IF;
    IF v_club_id IS NOT NULL AND v_club_id<>v_context_club THEN
      RAISE EXCEPTION 'wallet debit declared club does not own table %',p_table_id
        USING ERRCODE='22023';
    END IF;
    v_club_id:=v_context_club;
  END IF;

  IF p_related_entity_id IS NOT NULL
     AND lower(COALESCE(p_category,'')) IN
       ('tournament_buyin','tournament_rebuy','rebuy','reentry','addon') THEN
    IF NOT EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id=p_related_entity_id
                     AND t.club_id IS NOT NULL) THEN
      RAISE EXCEPTION 'wallet debit tournament % has no club context',
        p_related_entity_id USING ERRCODE='P0002';
    END IF;
    -- THE ENTRY IS CHARGED TO THE WALLET THE ENTRY IS STAMPED WITH
    -- (2026-09-10). trg_tournament_players_stamp_club stamps the entry with
    -- fn_tournament_club_for_user; the debit reads the same function with the
    -- same preferred club, so the wallet a prize returns to is the wallet the
    -- buy-in left. Reading tournaments.club_id here charged the union's house
    -- club for every union-hosted entry (3,232 entries / 73,659.00 in 24h).
    v_context_club:=public.fn_tournament_club_for_user(
      p_user_id,p_related_entity_id,v_club_id);
    IF v_context_club IS NULL THEN
      RAISE EXCEPTION 'no club wallet in the union of tournament % resolves for player %',
        p_related_entity_id,p_user_id USING ERRCODE='42501';
    END IF;
    IF v_club_id IS NOT NULL AND v_club_id<>v_context_club THEN
      RAISE EXCEPTION 'wallet debit declared club does not own tournament %',
        p_related_entity_id USING ERRCODE='22023';
    END IF;
    v_club_id:=v_context_club;
  END IF;

  IF v_club_id IS NULL THEN
    v_club_id:=public.fn_player_home_club(p_user_id,NULL);
  END IF;

  IF v_club_id IS NOT NULL THEN
    IF public.fn_ensure_club_wallet(p_user_id,v_club_id) IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'player % has no active wallet at club %',p_user_id,v_club_id
        USING ERRCODE='42501';
    END IF;
    SELECT cm.chip_balance INTO v_balance
      FROM public.club_members cm
     WHERE cm.user_id=p_user_id AND cm.club_id=v_club_id
       AND cm.status IN ('active','approved')
     FOR UPDATE;
    IF v_balance IS NULL OR v_balance<p_amount THEN
      RETURN false;
    END IF;
    /* THE CALLER NAMES WHERE THE CHIPS GO (2026-10-02, 20261002140203). This
       primitive debits a wallet for a door it does not know. Without a
       declared counterparty the club_members journal books the leg against
       settlement_suspense and the commit check refuses the transaction; say
       so here, by name, before anything moves. */
    IF NULLIF(current_setting('app.ledger_counterparty', true), '') IS NULL
       AND COALESCE(current_setting('app.ledger_autoskip_club_members', true), '') <> '1' THEN
      RAISE EXCEPTION 'atomic_deduct_wallet_and_log_requires_a_declared_counterparty'
        USING ERRCODE = '23514',
              DETAIL  = 'a player wallet debit with no app.ledger_counterparty would be journalled against settlement_suspense',
              HINT    = 'The calling door declares where the chips go (fn_ca_declare_ledger) before it calls, or stands the club_members journal down and writes its own leg.';
    END IF;
    UPDATE public.club_members cm
       SET chip_balance=cm.chip_balance-p_amount,updated_at=now()
     WHERE cm.user_id=p_user_id AND cm.club_id=v_club_id
       AND cm.status IN ('active','approved')
       AND cm.chip_balance>=p_amount;
    IF NOT FOUND THEN
      RETURN false;
    END IF;
    INSERT INTO public.chip_transactions(
      club_id,from_user_id,amount,transaction_type,notes
    ) VALUES (
      v_club_id,p_user_id,p_amount,p_category,
      COALESCE(NULLIF(p_description,''),'Wallet debit')
    );
    RETURN true;
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.club_members cm WHERE cm.user_id=p_user_id
  ) INTO v_has_club;
  IF v_has_club THEN
    RAISE EXCEPTION 'No active club wallet resolves for Club Arena debit from player %',
      p_user_id USING ERRCODE='42501';
  END IF;

  UPDATE public.wallets w
     SET balance=w.balance-p_amount,updated_at=now()
   WHERE w.user_id=p_user_id AND w.wallet_type='PLAYER'
     AND w.balance>=p_amount;
  RETURN FOUND;
END;
$function$

public.fn_cashier_event_messenger_thread.def:
CREATE OR REPLACE FUNCTION public.fn_cashier_event_messenger_thread()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE sender uuid; other uuid; page uuid; conv uuid; amt text; body text; note text;
BEGIN
 IF NEW.event_kind NOT IN('hold','approval','decline','cancellation') THEN RETURN NULL; END IF;
 BEGIN
  amt:=to_char(abs(NEW.amount),'FM999,999,999,999,990.00')||' Chips';
  note:=NULLIF(btrim(COALESCE(NEW.accepted_note,'')),'');
  IF NEW.event_kind IN('hold','cancellation') THEN sender:=NEW.player_id; other:=NEW.assigned_agent_id;
  ELSE sender:=NEW.actor_user_id; other:=NEW.player_id; END IF;
  IF sender IS NULL OR other IS NULL OR sender=other THEN RETURN NULL; END IF;
  body:=CASE NEW.event_kind
   WHEN 'hold' THEN 'Cashout Request: '||amt||E'\nPlease Accept Or Cancel My Payout In Invoices.'||COALESCE(E'\nNote: '||note,'')
   WHEN 'cancellation' THEN 'I Cancelled My Cashout Request Of '||amt||'.'
   WHEN 'approval' THEN 'Cashout Approved: '||amt||'. Your Payout Was Accepted.'||COALESCE(E'\nNote: '||note,'')
   ELSE 'Cashout Cancelled: '||amt||' Were Returned To Your Wallet.'||COALESCE(E'\nNote: '||note,'') END;
  SELECT id INTO page FROM public.social_pages WHERE linked_entity_id=NEW.club_id::text AND linked_entity_type='club' ORDER BY id LIMIT 1;
  PERFORM pg_advisory_xact_lock(hashtextextended('cashout-dm:'||COALESCE(page::text,'-')||':'||least(sender,other)::text||':'||greatest(sender,other)::text,0));
  SELECT c.id INTO conv FROM public.social_conversations c
   JOIN public.social_conversation_participants a ON a.conversation_id=c.id AND a.user_id=sender
   JOIN public.social_conversation_participants b ON b.conversation_id=c.id AND b.user_id=other
   WHERE c.is_group=false AND a.context_entity_id IS NOT DISTINCT FROM page AND b.context_entity_id IS NOT DISTINCT FROM page
     AND NOT EXISTS(SELECT 1 FROM public.social_conversation_participants x WHERE x.conversation_id=c.id AND x.user_id NOT IN(sender,other))
   ORDER BY c.last_message_at DESC NULLS LAST LIMIT 1;
  IF conv IS NULL THEN
   INSERT INTO public.social_conversations(is_group,context_entity_id,context_entity_type)
    VALUES(false,page,CASE WHEN page IS NULL THEN NULL ELSE 'club' END) RETURNING id INTO conv;
   INSERT INTO public.social_conversation_participants(conversation_id,user_id,context_entity_id,context_entity_type)
    VALUES(conv,sender,page,CASE WHEN page IS NULL THEN NULL ELSE 'club' END),
          (conv,other,page,CASE WHEN page IS NULL THEN NULL ELSE 'club' END);
  END IF;
  INSERT INTO public.social_messages(conversation_id,sender_id,content,message_type,media_metadata)
   VALUES(conv,sender,body,'text',jsonb_build_object('kind','cashout_request','event_kind',NEW.event_kind,
     'cashout_id',NEW.cashout_id,'club_id',NEW.club_id,'player_id',NEW.player_id,'amount',round(NEW.amount,2)::text,
     'invoice_id',NEW.invoice_id));
  UPDATE public.social_conversations SET last_message_at=now(),last_message_preview=left(body,100),updated_at=now() WHERE id=conv;
 EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'cashout messenger thread skipped for event %: %',NEW.id,SQLERRM;
 END;
 RETURN NULL;
END $function$

public.fn_ca_launch_cashier_request_boun.def:
CREATE OR REPLACE FUNCTION public.fn_ca_launch_cashier_request_boundary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE cut timestamptz;
BEGIN
 cut:=public.fn_ca_launch_accounting_cutoff('club',NEW.club_id);
 IF cut IS NULL THEN RETURN NEW; END IF;
 -- A delayed or backdated request cannot create an old obligation after launch.
 IF TG_OP='INSERT' AND (NEW.created_at IS NULL OR NEW.created_at<cut) THEN
  RAISE EXCEPTION 'LAUNCH_PREVIOUS_CASHIER_REQUEST_IS_WAIVED' USING ERRCODE='55000';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.created_at IS NULL OR OLD.created_at<cut)
   AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.club_id IS DISTINCT FROM OLD.club_id) THEN
  RAISE EXCEPTION 'LAUNCH_PREVIOUS_CASHIER_REQUEST_IS_WAIVED' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $function$

public.fn_ca_assert_emergency_path(p_pat.def:
CREATE OR REPLACE FUNCTION public.fn_ca_assert_emergency_path(p_path text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE active boolean;
BEGIN
 IF p_path IS NULL OR p_path NOT IN('tournament_registration','positive_issuance','cashout')
 THEN RAISE EXCEPTION 'unknown_emergency_path' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('ca-emergency-stop:'||p_path,0));
 SELECT stopped INTO active FROM public.ca_emergency_stops WHERE path=p_path FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'emergency_stop_authority_missing' USING ERRCODE='55000'; END IF;
 IF active THEN RAISE EXCEPTION 'emergency_path_stopped:%',p_path USING ERRCODE='P0410'; END IF;
END $function$
